    async fn insert_trace_events_batch(
        &self,
        rows: &[TraceEventRow],
    ) -> Result<InsertReport, Error> {
        if rows.is_empty() {
            return Ok(InsertReport::default());
        }

        let mut client = self.get_client().await?;
        let tx = client
            .transaction()
            .await
            .map_err(|e| Error::Backend(format!("begin tx: {e}")))?;

        // v32.1.0 (CIRISPersist#606) — ONE admission instant for the whole
        // batch, allocated inside this transaction.
        //
        // One per batch, not one per row: the rows of a batch arrived together,
        // so they were admitted together, and a per-row instant would invent an
        // ordering the arrival did not have.
        //
        // Through `monotonic_admission_instant` rather than a bare `now()`,
        // because `MAX(admitted_at)` is the liveness reading. Under a backward
        // clock step a bare now() writes values BELOW the existing max, so the
        // max freezes and the plane reads dark while traces are actively
        // landing — the same false-outage this issue exists to remove,
        // re-introduced from the other side. Reading the max inside the
        // transaction is what makes the allocation race-free against a
        // concurrent batch.
        let last_admitted: Option<chrono::DateTime<chrono::Utc>> = tx
            .query_one(
                "SELECT MAX(admitted_at)::TIMESTAMPTZ AS m FROM cirislens.trace_events",
                &[],
            )
            .await
            .map_err(|e| Error::Backend(format!("read max admitted_at: {e}")))?
            .try_get("m")
            .map_err(|e| Error::Backend(format!("decode max admitted_at: {e}")))?;
        let admitted_at = crate::federation::types::monotonic_admission_instant(
            crate::host::clock::now(),
            last_admitted,
        );

        // Build one INSERT ... VALUES (...), (...), ...
        // ON CONFLICT (trace_id, thought_id, event_type, attempt_index, ts)
        // DO NOTHING
        // The conflict target matches the V001 UNIQUE index
        // `trace_events_dedup`.
        const COLS: &str = "trace_id, thought_id, task_id, step_point, event_type, \
                            attempt_index, ts, agent_name, agent_id_hash, cognitive_state, \
                            trace_level, payload, cost_llm_calls, cost_tokens, cost_usd, \
                            signature, signing_key_id, signature_verified, schema_version, \
                            pii_scrubbed, audit_sequence_number, audit_entry_hash, audit_signature, \
                            original_content_hash, scrub_signature, scrub_key_id, scrub_timestamp, \
                            agent_role, agent_template, deployment_domain, \
                            deployment_type, deployment_region, deployment_trust_mode, \
                            verification_source, cohort_scope, cohort_target_id, \
                            pqc_key_id, \
                            shard_key, \
                            scrub_ner_ran, scrub_applied_trace_level, scrub_model_digest, \
                            admitted_at";
        // v32.0.0 (#690) — 40 -> 43, and now DERIVED rather than restated.
        //
        // The placeholder generator below multiplies by this, so a hand-kept
        // count that disagreed with `COLS` produced a runtime bind failure, not
        // a compile error — and only on a real Postgres, which the memory and
        // sqlite legs never reach. Counting the commas in `COLS` at compile
        // time makes the two impossible to disagree: same discipline as the
        // certify axis-key list (#694), one plane down.
        const fn count_cols(s: &str) -> usize {
            let b = s.as_bytes();
            let mut i = 0;
            let mut n = 1;
            while i < b.len() {
                if b[i] == b',' {
                    n += 1;
                }
                i += 1;
            }
            n
        }
        const N_COLS: usize = count_cols(COLS);

        let mut sql = String::with_capacity(2048);
        sql.push_str("INSERT INTO cirislens.trace_events (");
        sql.push_str(COLS);
        sql.push_str(") VALUES ");

        let mut params: Vec<Box<dyn ToSql + Sync + Send>> = Vec::with_capacity(rows.len() * N_COLS);
        for (i, row) in rows.iter().enumerate() {
            if i > 0 {
                sql.push(',');
            }
            sql.push('(');
            for c in 0..N_COLS {
                if c > 0 {
                    sql.push(',');
                }
                let placeholder_idx = i * N_COLS + c + 1;
                sql.push('$');
                sql.push_str(&placeholder_idx.to_string());
            }
            sql.push(')');

            // Audit anchor extraction — only ACTION_RESULT rows.
            let (audit_seq, audit_hash, audit_sig): (Option<i64>, Option<String>, Option<String>) =
                if row.event_type == ReasoningEventType::ActionResult {
                    let seq = row
                        .payload
                        .get("audit_sequence_number")
                        .and_then(|v| v.as_i64());
                    let hash = row
                        .payload
                        .get("audit_entry_hash")
                        .and_then(|v| v.as_str())
                        .map(str::to_owned);
                    let sig = row
                        .payload
                        .get("audit_signature")
                        .and_then(|v| v.as_str())
                        .map(str::to_owned);
                    (seq, hash, sig)
                } else {
                    (None, None, None)
                };

            params.push(Box::new(row.trace_id.clone()));
            params.push(Box::new(row.thought_id.clone()));
            params.push(Box::new(row.task_id.clone()));
            params.push(Box::new(row.step_point.clone()));
            params.push(Box::new(row.event_type.as_str().to_owned()));
            // THREAT_MODEL.md AV-17 (v0.1.3): bounded by
            // schema::MAX_ATTEMPT_INDEX at parse time, so this fits in i32.
            // `try_from` rejects out-of-range explicitly instead of
            // silently wrapping.
            params.push(Box::new(i32::try_from(row.attempt_index).map_err(
                |_| {
                    Error::Backend(format!(
                        "attempt_index {} exceeds i32::MAX (postgres INT)",
                        row.attempt_index
                    ))
                },
            )?));
            params.push(Box::new(row.ts));
            params.push(Box::new(row.agent_name.clone()));
            params.push(Box::new(row.agent_id_hash.clone()));
            params.push(Box::new(row.cognitive_state.clone()));
            params.push(Box::new(trace_level_str(row.trace_level).to_owned()));
            params.push(Box::new(serde_json::Value::Object(row.payload.clone())));
            params.push(Box::new(row.cost_llm_calls));
            params.push(Box::new(row.cost_tokens));
            params.push(Box::new(row.cost_usd));
            params.push(Box::new(row.signature.clone()));
            params.push(Box::new(row.signing_key_id.clone()));
            params.push(Box::new(row.signature_verified));
            params.push(Box::new(row.schema_version.clone()));
            params.push(Box::new(row.pii_scrubbed));
            params.push(Box::new(audit_seq));
            params.push(Box::new(audit_hash));
            params.push(Box::new(audit_sig));
            // v0.1.3 scrub envelope columns (V003).
            params.push(Box::new(row.original_content_hash.clone()));
            params.push(Box::new(row.scrub_signature.clone()));
            params.push(Box::new(row.scrub_key_id.clone()));
            params.push(Box::new(row.scrub_timestamp));
            // v0.3.4 deployment_profile columns (V006).
            params.push(Box::new(row.agent_role.clone()));
            params.push(Box::new(row.agent_template.clone()));
            params.push(Box::new(row.deployment_domain.clone()));
            params.push(Box::new(row.deployment_type.clone()));
            params.push(Box::new(row.deployment_region.clone()));
            params.push(Box::new(row.deployment_trust_mode.clone()));
            // v2.0 verification_source column (V044, #91).
            params.push(Box::new(row.verification_source.as_wire_str().to_owned()));
            // v4.0 cohort_scope + target columns (V060, #160). The
            // ingest pipeline resolved the self-target already; persist
            // records the (scope, target) the §4.3 read-gate filters on.
            params.push(Box::new(row.cohort_scope.clone()));
            params.push(Box::new(row.cohort_target_id.clone()));
            // v7.2.0 per-trace ML-DSA-65 hybrid columns (V083, #225).
            // The producer's PQC half of the per-trace envelope sig; the
            // ingest gate rejected Full-mode classical-only before this.
            // CIRISPersist#789 — neither is written per-event any more. The
            // signature is thought-scoped and lives once in
            // `trace_thought_signatures`; the pubkey is key-scoped and is
            // resolved from the directory by `pqc_key_id`, the column that
            // stays. 679 MB of an 898 MB table was these two copies.
            params.push(Box::new(row.pqc_key_id.clone()));
            // #226 — app-level dedup shard (V094). Deterministic FNV over
            // a subset of the dedup key; a true duplicate computes the same
            // shard and still collides on the sharded UNIQUE index below.
            params.push(Box::new(super::decompose::trace_dedup_shard_key(row)));
            // v32.0.0 (#690, V127) — the scrub TREATMENT claims. These sit
            // INSIDE the `scrub_signature` preimage, so a row written without
            // them carries a signature nobody can ever check.
            params.push(Box::new(row.scrub_ner_ran));
            params.push(Box::new(row.scrub_applied_trace_level.clone()));
            params.push(Box::new(row.scrub_model_digest.clone()));
            // v32.1.0 (#606) — the batch's admission instant. NOT
            // `row.admitted_at`: the backend stamps this, so a caller cannot
            // assert when this node received its bytes. `ON CONFLICT DO
            // NOTHING` leaves an existing row's value alone — a re-delivery is
            // not an arrival, and letting a replay refresh the instant would
            // make a stuck producer look live.
            params.push(Box::new(admitted_at));
        }
        // THREAT_MODEL.md AV-9: dedup-key target still includes
        // agent_id_hash so a malicious agent reusing another agent's
        // trace_id/thought_id shape cannot DOS the victim's traces.
        // #226 (V094): PREFIXED with shard_key so concurrent inserts
        // spread across 64 disjoint B-tree subtrees instead of one hot
        // page. shard_key is a pure function of the other key columns, so
        // this forbids exactly the rows the old 6-column index did.
        // Matches the V094 trace_events_dedup_sharded UNIQUE index.
        sql.push_str(
            " ON CONFLICT (shard_key, agent_id_hash, trace_id, thought_id, \
             event_type, attempt_index, ts) DO NOTHING",
        );

        let params_refs: Vec<&(dyn ToSql + Sync)> = params
            .iter()
            .map(|b| b.as_ref() as &(dyn ToSql + Sync))
            .collect();

        let inserted = tx
            .execute(sql.as_str(), &params_refs)
            .await
            .map_err(|e| Error::Backend(format!("insert trace_events: {e}")))?;

        // CIRISPersist#789 — the thought-scoped signature, written ONCE per
        // thought, in the SAME transaction as the events it covers.
        //
        // Same transaction is the point: a crash between the two writes would
        // leave events whose signature was never stored, and that signature is
        // recoverable from nowhere else.
        //
        // `DO NOTHING` on conflict because the signature is a total function
        // of `thought_id` — every event of a thought carries the same one, so
        // the first write wins and the rest are identical bytes. A DIFFERING
        // signature for one thought would be a producer bug, and it is refused
        // loudly by the V135 backfill's PRIMARY KEY rather than silently
        // overwritten here.
        for row in rows {
            // Bound before the call: `as_deref` refuses nothing, so it does not
            // belong inside a `?`-propagated expression — the parity gate asks
            // what each call on that path refuses, and "nothing" is the wrong
            // answer to have to give.
            let key = row.pqc_key_id.clone();
            let sig = row.signature_ml_dsa_65.clone();
            if let Some(sig) = sig {
                tx.execute(
                    "INSERT INTO cirislens.trace_thought_signatures \
                         (thought_id, signature_ml_dsa_65, pqc_key_id) \
                     VALUES ($1, $2, $3) \
                     ON CONFLICT (thought_id) DO NOTHING",
                    &[&row.thought_id, &sig, &key],
                )
                .await
                .map_err(|e| Error::Backend(format!("insert trace_thought_signatures: {e}")))?;
            }
        }

        tx.commit()
            .await
            .map_err(|e| Error::Backend(format!("commit: {e}")))?;

        let inserted = inserted as usize;
        Ok(InsertReport {
            inserted,
            conflicted: rows.len().saturating_sub(inserted),
        })
    }

    async fn insert_trace_llm_calls_batch(&self, rows: &[TraceLlmCallRow]) -> Result<usize, Error> {
        if rows.is_empty() {
            return Ok(0);
        }
        let mut client = self.get_client().await?;
        let tx = client
            .transaction()
            .await
            .map_err(|e| Error::Backend(format!("begin tx: {e}")))?;

        const COLS: &str = "trace_id, thought_id, task_id, parent_event_id, parent_event_type, \
                            parent_attempt_index, attempt_index, ts, duration_ms, handler_name, \
                            service_name, model, base_url, response_model, prompt_tokens, \
                            completion_tokens, prompt_bytes, completion_bytes, cost_usd, status, \
                            error_class, attempt_count, retry_count, prompt_hash, prompt, \
                            response_text";
        const N_COLS: usize = 26;

        let mut sql = String::with_capacity(2048);
        sql.push_str("INSERT INTO cirislens.trace_llm_calls (");
        sql.push_str(COLS);
        sql.push_str(") VALUES ");

        let mut params: Vec<Box<dyn ToSql + Sync + Send>> = Vec::with_capacity(rows.len() * N_COLS);
        for (i, r) in rows.iter().enumerate() {
            if i > 0 {
                sql.push(',');
            }
            sql.push('(');
            for c in 0..N_COLS {
                if c > 0 {
                    sql.push(',');
                }
                let placeholder_idx = i * N_COLS + c + 1;
                sql.push('$');
                sql.push_str(&placeholder_idx.to_string());
            }
            sql.push(')');

            params.push(Box::new(r.trace_id.clone()));
            params.push(Box::new(r.thought_id.clone()));
            params.push(Box::new(r.task_id.clone()));
            params.push(Box::new(r.parent_event_id));
            params.push(Box::new(r.parent_event_type.as_str().to_owned()));
            // THREAT_MODEL.md AV-17 (v0.1.3): same bound on parent_attempt_index.
            params.push(Box::new(i32::try_from(r.parent_attempt_index).map_err(
                |_| {
                    Error::Backend(format!(
                        "parent_attempt_index {} exceeds i32::MAX",
                        r.parent_attempt_index
                    ))
                },
            )?));
            // Same bound for the LLM_CALL row's own attempt_index.
            params.push(Box::new(i32::try_from(r.attempt_index).map_err(|_| {
                Error::Backend(format!(
                    "attempt_index {} exceeds i32::MAX",
                    r.attempt_index
                ))
            })?));
            params.push(Box::new(r.ts));
            params.push(Box::new(r.duration_ms));
            params.push(Box::new(r.handler_name.clone()));
            params.push(Box::new(r.service_name.clone()));
            params.push(Box::new(r.model.clone()));
            params.push(Box::new(r.base_url.clone()));
            params.push(Box::new(r.response_model.clone()));
            params.push(Box::new(r.prompt_tokens));
            params.push(Box::new(r.completion_tokens));
            params.push(Box::new(r.prompt_bytes));
            params.push(Box::new(r.completion_bytes));
            params.push(Box::new(r.cost_usd));
            params.push(Box::new(llm_status_str(r.status).to_owned()));
            params.push(Box::new(r.error_class.clone()));
            params.push(Box::new(r.attempt_count));
            params.push(Box::new(r.retry_count));
            params.push(Box::new(r.prompt_hash.clone()));
            params.push(Box::new(r.prompt.clone()));
            params.push(Box::new(r.response_text.clone()));
        }

        let params_refs: Vec<&(dyn ToSql + Sync)> = params
            .iter()
            .map(|b| b.as_ref() as &(dyn ToSql + Sync))
            .collect();

        let inserted = tx
            .execute(sql.as_str(), &params_refs)
            .await
            .map_err(|e| Error::Backend(format!("insert trace_llm_calls: {e}")))?;

        tx.commit()
            .await
            .map_err(|e| Error::Backend(format!("commit llm_calls: {e}")))?;

        Ok(inserted as usize)
    }

    /// v0.7.4 (CIRISPersist#19) — batch-UPDATE the V009
    /// `extracted_features` column for `(trace_id, thought_id)` pairs
    /// the post-ingest pipeline ran extract on. Called from
    /// `IngestPipeline::receive_and_persist` after the row INSERT.
    ///
    /// Bulk path uses `UNNEST` of three arrays — single round-trip
    /// regardless of batch size. Returns the affected-row count;
    /// caller uses for diagnostic / metrics purposes (count drift
    /// signals INSERT/UPDATE skew, not a hard failure).
    ///
    /// Idempotent: re-running with the same inputs replaces the JSONB
    /// value (UPDATE-by-equality, no Conflict surface).
    #[cfg(feature = "extract")]
    async fn update_features_batch(
        &self,
        updates: &[(String, String, crate::pipeline::extract::Features)],
    ) -> Result<u64, Error> {
        if updates.is_empty() {
            return Ok(0);
        }
        let trace_ids: Vec<&str> = updates.iter().map(|(t, _, _)| t.as_str()).collect();
        let thought_ids: Vec<&str> = updates.iter().map(|(_, th, _)| th.as_str()).collect();
        let features_json: Vec<serde_json::Value> = updates
            .iter()
            .map(|(_, _, f)| serde_json::to_value(f))
            .collect::<Result<_, _>>()
            .map_err(|e| Error::Backend(format!("features serialize: {e}")))?;

        let client = self.get_client().await?;
        let n = client
            .execute(
                "UPDATE cirislens.trace_events AS t \
                 SET extracted_features = u.features \
                 FROM (\
                     SELECT \
                         UNNEST($1::text[]) AS trace_id, \
                         UNNEST($2::text[]) AS thought_id, \
                         UNNEST($3::jsonb[]) AS features\
                 ) AS u \
                 WHERE t.trace_id = u.trace_id AND t.thought_id = u.thought_id",
                &[&trace_ids, &thought_ids, &features_json],
            )
            .await
            .map_err(|e| Error::Backend(format!("update_features_batch: {e}")))?;
        Ok(n)
    }

    async fn run_migrations(&self) -> Result<(), Error> {
        // v24.1.0 (CIRISPersist#559) — THE DDL RUNS ONCE PER PROCESS, PER
        // DATABASE. `Engine(...)` re-enters this on every construction, and
        // even a steady-state boot took the global advisory lock and re-ran
        // refinery. See `migration_guard` for the #937 story and for why this
        // is NOT the mutual exclusion (the advisory lock below still is).
        //
        // The guard covers the DDL and ONLY the DDL — the shard-key backfill
        // at the tail is a data-repair sweep and runs on every call, including
        // through the early return just below.
        if !migration_guard::needs_migration(&self.dsn) {
            tracing::debug!(
                "ciris-persist: migration phase already completed in this process for this \
                 database — skipping the DDL (CIRISPersist#559)"
            );
            // The shard-key backfill still runs — see the comment at the tail
            // of this function for why it is NOT under the guard.
            self.backfill_trace_dedup_shard_keys().await?;
            // v62.0.0 (wave G0 v4) — the interrupted re-fold repair, here too.
            crate::federation::edition2::fold::repair_at_open(self)
                .await
                .map_err(|e| Error::Backend(format!("fold repair at open: {e}")))?;
            return Ok(());
        }
        migration_guard::note_phase_entered();

        // v0.1.5 — multi-worker boot race fix. Before this, two
        // workers calling `run_migrations` concurrently against the
        // same DB would race on Postgres's catalog (`pg_type` insert
        // for hypertable types, `IF NOT EXISTS` checks across the
        // V001 + V003 set, refinery's own schema_history table).
        // Pre-v0.1.5 the second worker saw "error asserting
        // migrations table — db error" with no SQLSTATE handle.
        //
        // Fix: take a session-scoped advisory lock on a dedicated
        // single-use connection. The first worker acquires it
        // immediately; subsequent workers block on
        // `pg_advisory_lock` until the first worker drops its
        // connection. Lock auto-releases on connection close — even
        // if the first worker panics mid-migration. THREAT_MODEL.md
        // AV-26.
        let mut lock_client = self.dedicated_connect().await?;

        // v24.1.0 (CIRISPersist#559) — bound every DDL statement's LOCK wait
        // before taking the advisory lock, so the bound also covers the
        // acquisition below. Without this, `dedicated_connect` opened a session
        // with no GUCs and every statement refinery ran waited forever for its
        // table lock — which is literally what #937's `pg_stat_activity` shows.
        //
        // The DSN is still honoured VERBATIM (`dedicated_connect` passes
        // `&self.dsn` straight through), and a consumer that already set
        // `lock_timeout` there — CIRISAgent 2.9.7 appends
        // `options=-c%20lock_timeout%3D120s` — KEEPS its value: we only supply
        // a default when the session has none. A first-class field that
        // silently overrode the seam the consumer is currently reaching through
        // would break the workaround this is meant to replace.
        self.apply_migration_lock_timeout(&lock_client).await?;

        // v24.1.0 (CIRISPersist#559) — a BOUNDED acquisition. This was
        // `pg_advisory_lock`, which blocks forever; a follower could not bound
        // its own wait and, with no output, looked hung rather than patient.
        // The try-loop carries its own (much more generous) budget and says
        // WHY it is waiting while it does.
        self.acquire_migration_lock(&lock_client).await?;

        tracing::info!(
            lock_id = MIGRATION_LOCK_ID,
            "ciris-persist: migration phase begin (advisory lock acquired)"
        );

        // v62.0.0 (slice E2b) — THE EDITION UPGRADE, inside the advisory
        // lock and before the runner: an edition-1 store is found, guarded
        // (a live legal hold or a store persist did not create refuses, and
        // nothing is deleted), counted and deleted; the runner then builds
        // the fresh edition-2 store, and the deletion is recorded in it.
        let upgrade = crate::store::edition_upgrade::postgres::upgrade_locked(
            &mut lock_client,
            crate::store::edition_upgrade::UpgradeMode::Delete,
        )
        .await;
        let (report, earlier) = match upgrade {
            Ok(r) => r,
            Err(e) => {
                let _ = lock_client
                    .execute("SELECT pg_advisory_unlock($1)", &[&MIGRATION_LOCK_ID])
                    .await;
                return Err(e);
            }
        };

        // The runner on the same lock-holding connection: each migration and
        // its history row in one transaction; the advisory lock is at session
        // scope, so it persists across all of them.
        //
        // v3.12.x (CIRISPersist#156) — the migration-timing diagnostic
        // silently no-ops without `CIRIS_PERSIST_MIGRATION_TIMING_LOG` set.
        let migration_started = crate::host::clock::monotonic_now();
        // v62.0.0 (P6) — persist's runner, refinery's decisions and rows;
        // the instant is the caller's (the Clock seam wires it).
        let report_result = crate::store::migration_runner::run_postgres(
            &mut lock_client,
            &crate::store::migration_runner::postgres_migrations(),
            None,
            &crate::host::clock::now,
        )
        .await;
        let elapsed = migration_started.elapsed();
        let mut migration_result = match report_result {
            Ok(report) => {
                let applied = report.versions();
                let applied_versions = applied
                    .iter()
                    .map(i32::to_string)
                    .collect::<Vec<_>>()
                    .join(",");
                crate::store::migration_timing::append(
                    &crate::store::migration_timing::MigrationTiming {
                        backend: "postgres",
                        elapsed,
                        applied_count: applied.len(),
                        applied_versions,
                    },
                );
                Ok(())
            }
            Err(e) => Err(runner_error("migrations", e)),
        };
        // The local-tier record of the deletion, in the fresh store.
        if let (Ok(()), Some(earlier), Some(at)) =
            (&migration_result, earlier.as_ref(), report.deleted_at)
        {
            migration_result =
                crate::store::edition_upgrade::postgres::record(&lock_client, earlier, at).await;
        }

        // Best-effort explicit unlock — graceful path. The drop below
        // is the actual guarantee (session ends → lock releases),
        // but releasing explicitly returns the lock as soon as the
        // last migration commits, shaving wait time off concurrent
        // workers.
        let _ = lock_client
            .execute("SELECT pg_advisory_unlock($1)", &[&MIGRATION_LOCK_ID])
            .await;
        drop(lock_client);

        migration_result?;
        *self
            .edition_upgrade_report
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(report);

        // v24.1.0 (CIRISPersist#559) — marked ONLY here, on the success path,
        // and BEFORE the backfill because the backfill is not part of what the
        // guard covers. Every early `?` above leaves the DSN unmarked so the
        // next construction retries: a database that failed to migrate but
        // reports itself migrated is strictly worse than the stampede.
        migration_guard::mark_migrated(&self.dsn);
        tracing::info!("ciris-persist: migration phase complete");

        // #226 (V094) — backfill shard_key for legacy rows, before the
        // engine serves any write. See `backfill_trace_dedup_shard_keys`.
        // Run on a pooled connection (the lock connection is already
        // dropped); the UPDATE is idempotent + safe under a concurrent
        // second worker (a row it sets no longer matches `IS NULL`).
        //
        // v24.1.0 (CIRISPersist#559) — DELIBERATELY OUTSIDE the once-guard,
        // and reached by the early-return above too. This is a DATA REPAIR
        // sweep, not DDL: it takes no lock, creates nothing, and fixes rows a
        // legacy writer left with a NULL shard_key. #559 is about DDL
        // stampeding a shared database; silently retiring a repair pass after
        // the first construction is a different change, and not one the issue
        // asks for. The first draft did put it under the guard, and
        // `dedup_shard::postgres_legacy_backfill_and_reingest_dedup` — which
        // nulls a shard key and re-runs migrations expecting it filled —
        // caught it. Cheap when there is nothing to do (one indexed SELECT).
        self.backfill_trace_dedup_shard_keys().await?;
        // v62.0.0 (wave G0 v4; CC 2.7.3) — a re-fold interrupted between
        // taking a row out of its typed table and recording why (`refolding`)
        // is repaired before anything serves. One indexed probe when none is.
        crate::federation::edition2::fold::repair_at_open(self)
            .await
            .map_err(|e| Error::Backend(format!("fold repair at open: {e}")))?;
        // v61 (the canonical's read storm) — planner statistics, last.
        self.plan_statistics_at_open().await;
        Ok(())
    }

