    async fn fetch_trace_events_page(
        &self,
        after_event_id: i64,
        limit: i64,
        agent_id_hash: Option<&str>,
    ) -> Result<Vec<(i64, TraceEventRow)>, Error> {
        let client = self.get_client().await?;

        // Branch on filter so the no-filter case skips the optional
        // WHERE-clause bind. Same shape Postgres planners optimize
        // either way; the bind-arity branch is the simplest readable form.
        let rows = match agent_id_hash {
            Some(h) => client
                .query(
                    "SELECT event_id, trace_id, thought_id, task_id, step_point, event_type, \
                            attempt_index, ts, agent_name, agent_id_hash, cognitive_state, \
                            trace_level, payload, cost_llm_calls, cost_tokens, cost_usd, \
                            signature, signing_key_id, signature_verified, schema_version, \
                            pii_scrubbed, audit_sequence_number, audit_entry_hash, \
                            audit_signature, original_content_hash, scrub_signature, \
                            scrub_key_id, scrub_timestamp, \
                            scrub_ner_ran, scrub_applied_trace_level, scrub_model_digest, \
                            admitted_at, \
                            agent_role, agent_template, \
                            deployment_domain, deployment_type, deployment_region, \
                            deployment_trust_mode, verification_source, \
                            cohort_scope, cohort_target_id, \
                            (SELECT s.signature_ml_dsa_65 \
                               FROM cirislens.trace_thought_signatures s \
                              WHERE s.thought_id = cirislens.trace_events.thought_id \
                                AND cirislens.trace_events.pqc_key_id IS NOT NULL) \
                              AS signature_ml_dsa_65, \
                            (SELECT k.pubkey_ml_dsa_65_base64 \
                               FROM cirislens.federation_keys k \
                              WHERE k.key_id = cirislens.trace_events.pqc_key_id) \
                              AS pubkey_ml_dsa_65, \
                            pqc_key_id \
                     FROM cirislens.trace_events \
                     WHERE event_id > $1 AND agent_id_hash = $2 \
                     ORDER BY event_id ASC LIMIT $3",
                    &[&after_event_id, &h, &limit],
                )
                .await
                .map_err(|e| Error::Backend(format!("fetch_trace_events_page: {e}")))?,
            None => client
                .query(
                    "SELECT event_id, trace_id, thought_id, task_id, step_point, event_type, \
                            attempt_index, ts, agent_name, agent_id_hash, cognitive_state, \
                            trace_level, payload, cost_llm_calls, cost_tokens, cost_usd, \
                            signature, signing_key_id, signature_verified, schema_version, \
                            pii_scrubbed, audit_sequence_number, audit_entry_hash, \
                            audit_signature, original_content_hash, scrub_signature, \
                            scrub_key_id, scrub_timestamp, \
                            scrub_ner_ran, scrub_applied_trace_level, scrub_model_digest, \
                            admitted_at, \
                            agent_role, agent_template, \
                            deployment_domain, deployment_type, deployment_region, \
                            deployment_trust_mode, verification_source, \
                            cohort_scope, cohort_target_id, \
                            (SELECT s.signature_ml_dsa_65 \
                               FROM cirislens.trace_thought_signatures s \
                              WHERE s.thought_id = cirislens.trace_events.thought_id \
                                AND cirislens.trace_events.pqc_key_id IS NOT NULL) \
                              AS signature_ml_dsa_65, \
                            (SELECT k.pubkey_ml_dsa_65_base64 \
                               FROM cirislens.federation_keys k \
                              WHERE k.key_id = cirislens.trace_events.pqc_key_id) \
                              AS pubkey_ml_dsa_65, \
                            pqc_key_id \
                     FROM cirislens.trace_events \
                     WHERE event_id > $1 \
                     ORDER BY event_id ASC LIMIT $2",
                    &[&after_event_id, &limit],
                )
                .await
                .map_err(|e| Error::Backend(format!("fetch_trace_events_page: {e}")))?,
        };

        rows.into_iter().map(pg_row_to_event_row).collect()
    }

    // ─── v8.0.0 — fountain content primitive (CIRISPersist#227) ─────

    async fn put_fountain_content(
        &self,
        manifest: &crate::fountain::FountainManifestV1,
        symbols: &[crate::fountain::FountainSymbolV1],
    ) -> Result<(), Error> {
        super::backend_plan::put_fountain_content_planned(self, manifest, symbols).await
    }

    async fn evict_fountain_content_to_tier(
        &self,
        content_id: &str,
        corpus_kind: &str,
        tier: crate::fountain::FountainTier,
    ) -> Result<u64, Error> {
        // Need the manifest's params to compute the keep-count.
        let Some(manifest) = self.fountain_manifest_row(content_id, corpus_kind).await? else {
            return Ok(0);
        };
        let keep = tier.keep_count(&manifest) as i64;

        let client = self.get_client().await?;
        // Evict everything OUTSIDE the keep set: order by
        // retention_priority ASC (keep-longest first), symbol_id ASC for
        // a deterministic tie-break, keep the first `keep`, delete the
        // rest. The DELETE uses a window over the same ORDER BY.
        let rows = client
            .execute(
                "DELETE FROM cirislens.content_symbols \
                 WHERE content_id = $1 AND symbol_id IN ( \
                   SELECT symbol_id FROM ( \
                     SELECT symbol_id, ROW_NUMBER() OVER ( \
                       ORDER BY retention_priority ASC, symbol_id ASC) AS rn \
                     FROM cirislens.content_symbols WHERE content_id = $1 \
                   ) ranked WHERE ranked.rn > $2 )",
                &[&content_id, &keep],
            )
            .await
            .map_err(|e| Error::Backend(format!("evict content_symbols: {e}")))?;
        Ok(rows)
    }

    async fn evict_fountain_content_hard_delete(
        &self,
        content_id: &str,
        corpus_kind: &str,
    ) -> Result<u64, Error> {
        // Manifest stays (EnvelopeOnly provenance); unknown content ⇒ no-op.
        if self
            .fountain_manifest_row(content_id, corpus_kind)
            .await?
            .is_none()
        {
            return Ok(0);
        }
        let client = self.get_client().await?;
        // Drop ALL symbols — never consults retention_priority (N5:
        // revocation overrides rarity; the §8.1.11.3 deletion-SLA wins).
        let rows = client
            .execute(
                "DELETE FROM cirislens.content_symbols WHERE content_id = $1",
                &[&content_id],
            )
            .await
            .map_err(|e| Error::Backend(format!("hard_delete content_symbols: {e}")))?;
        Ok(rows)
    }

    async fn get_fountain_content(
        &self,
        content_id: &str,
        corpus_kind: &str,
    ) -> Result<Option<crate::fountain::FountainContent>, Error> {
        let Some(manifest) = self.fountain_manifest_row(content_id, corpus_kind).await? else {
            return Ok(None);
        };
        let client = self.get_client().await?;
        let rows = client
            .query(
                "SELECT content_id, symbol_id, retention_priority, symbol_bytes \
                 FROM cirislens.content_symbols WHERE content_id = $1 \
                 ORDER BY symbol_id ASC",
                &[&content_id],
            )
            .await
            .map_err(|e| Error::Backend(format!("read content_symbols: {e}")))?;
        let mut symbols = Vec::with_capacity(rows.len());
        for row in &rows {
            let sym_id: i64 = row.safe_get_with("symbol_id", Error::Backend)?;
            let priority: i16 = row.safe_get_with("retention_priority", Error::Backend)?;
            let bytes: Vec<u8> = row.safe_get_with("symbol_bytes", Error::Backend)?;
            let cid: String = row.safe_get_with("content_id", Error::Backend)?;
            symbols.push(crate::fountain::FountainSymbolV1 {
                content_id: cid,
                symbol_id: u32::try_from(sym_id)
                    .map_err(|_| Error::Backend("symbol_id out of u32 range".into()))?,
                retention_priority: u8::try_from(priority)
                    .map_err(|_| Error::Backend("retention_priority out of u8 range".into()))?,
                symbol_bytes: bytes,
            });
        }
        Ok(Some(super::fountain_read::assemble_fountain_content(
            manifest, symbols,
        )?))
    }

    // #227 — publisher-facing held fountain-content enumerator.
    async fn list_held_fountain_content(
        &self,
        publisher_key_id: &str,
    ) -> Result<Vec<crate::fountain::FountainHeldMeta>, Error> {
        let client = self.get_client().await?;
        let rows = client
            .query(
                "SELECT m.content_id, m.corpus_kind, m.pqc_key_id, \
                        m.original_content_length, m.n_source, m.k_repair, \
                        m.min_viable_symbols, m.symbol_size, m.admitted_at, \
                        (SELECT COUNT(*) FROM cirislens.content_symbols s \
                         WHERE s.content_id = m.content_id) AS held, \
                        m.envelope \
                 FROM cirislens.content_manifest m WHERE m.pqc_key_id = $1 \
                 ORDER BY m.admitted_at DESC, m.content_id ASC",
                &[&publisher_key_id],
            )
            .await
            .map_err(|e| Error::Backend(format!("list_held_fountain_content: {e}")))?;
        let mut out = Vec::with_capacity(rows.len());
        for r in rows {
            let min_viable: i64 = r.safe_get_with("min_viable_symbols", Error::Backend)?;
            let held: i64 = r.safe_get_with("held", Error::Backend)?;
            let admitted_at: chrono::DateTime<chrono::Utc> =
                r.safe_get_with("admitted_at", Error::Backend)?;
            let symbol_size =
                u32::try_from(r.safe_get_with::<i64, _, _, _>("symbol_size", Error::Backend)?)
                    .unwrap_or(0);
            // cohort_scope: #349 — read from the signed envelope (JSONB → Value);
            // a missing key yields None (unscoped / legacy content).
            let envelope: serde_json::Value = r.safe_get_with("envelope", Error::Backend)?;
            let cohort_scope = crate::fountain::cohort_scope_from_envelope(&envelope);
            out.push(crate::fountain::FountainHeldMeta {
                content_id: r.safe_get_with("content_id", Error::Backend)?,
                corpus_kind: r.safe_get_with("corpus_kind", Error::Backend)?,
                pqc_key_id: r.safe_get_with("pqc_key_id", Error::Backend)?,
                original_content_length: u64::try_from(
                    r.safe_get_with::<i64, _, _, _>("original_content_length", Error::Backend)?,
                )
                .unwrap_or(0),
                n_source: u32::try_from(
                    r.safe_get_with::<i64, _, _, _>("n_source", Error::Backend)?,
                )
                .unwrap_or(0),
                k_repair: u32::try_from(
                    r.safe_get_with::<i64, _, _, _>("k_repair", Error::Backend)?,
                )
                .unwrap_or(0),
                min_viable_symbols: u32::try_from(min_viable).unwrap_or(0),
                symbol_size,
                held_symbols: u32::try_from(held).unwrap_or(0),
                content_bytes: u64::try_from(held).unwrap_or(0) * u64::from(symbol_size),
                cohort_scope,
                recoverable: held >= min_viable,
                admitted_at: admitted_at.to_rfc3339(),
            });
        }
        Ok(out)
    }

    // ─── v13.0.0 — §Q pin-INSTALL surface (CIRISPersist#370) ─────────

    async fn put_installed_storage_budget(
        &self,
        budget: &crate::fountain::storage_contention::InstalledStorageBudget,
    ) -> Result<bool, Error> {
        let revision = i64::try_from(budget.revision)
            .map_err(|_| Error::Backend("storage budget revision exceeds i64".into()))?;
        let scopes = serde_json::to_value(&budget.scopes)
            .map_err(|e| Error::Backend(format!("serialize budget scopes: {e}")))?;
        let pinned_class = serde_json::to_value(&budget.pinned_class)
            .map_err(|e| Error::Backend(format!("serialize budget pinned_class: {e}")))?;
        let wire: serde_json::Value = serde_json::from_str(&budget.wire_json)
            .map_err(|e| Error::Backend(format!("parse budget wire json: {e}")))?;
        let client = self.get_client().await?;
        // §Q B3 anti-rollback, ATOMIC at the row: the DO UPDATE only fires
        // when the incoming revision is STRICTLY higher; rows_affected == 0
        // ⇒ refused (the Engine surfaces RevisionRollback).
        let n = client
            .execute(
                "INSERT INTO cirislens.storage_budget_installed (\
                     node_id, revision, epoch_id, scopes, pinned_class, wire, installed_at\
                 ) VALUES ($1,$2,$3,$4,$5,$6,$7) \
                 ON CONFLICT (node_id) DO UPDATE SET \
                     revision = EXCLUDED.revision, \
                     epoch_id = EXCLUDED.epoch_id, \
                     scopes = EXCLUDED.scopes, \
                     pinned_class = EXCLUDED.pinned_class, \
                     wire = EXCLUDED.wire, \
                     installed_at = EXCLUDED.installed_at \
                 WHERE storage_budget_installed.revision < EXCLUDED.revision",
                &[
                    &budget.node_id,
                    &revision,
                    &budget.epoch_id,
                    &scopes,
                    &pinned_class,
                    &wire,
                    &budget.installed_at,
                ],
            )
            .await
            .map_err(|e| Error::Backend(format!("put_installed_storage_budget: {e}")))?;
        Ok(n > 0)
    }

    async fn get_installed_storage_budget(
        &self,
        node_id: &str,
    ) -> Result<Option<crate::fountain::storage_contention::InstalledStorageBudget>, Error> {
        let client = self.get_client().await?;
        let row = client
            .query_opt(
                "SELECT node_id, revision, epoch_id, scopes, pinned_class, wire, installed_at \
                 FROM cirislens.storage_budget_installed WHERE node_id = $1",
                &[&node_id],
            )
            .await
            .map_err(|e| Error::Backend(format!("get_installed_storage_budget: {e}")))?;
        row.map(pg_row_to_installed_storage_budget).transpose()
    }

    async fn list_installed_storage_budgets(
        &self,
    ) -> Result<Vec<crate::fountain::storage_contention::InstalledStorageBudget>, Error> {
        let client = self.get_client().await?;
        let rows = client
            .query(
                "SELECT node_id, revision, epoch_id, scopes, pinned_class, wire, installed_at \
                 FROM cirislens.storage_budget_installed ORDER BY node_id ASC",
                &[],
            )
            .await
            .map_err(|e| Error::Backend(format!("list_installed_storage_budgets: {e}")))?;
        rows.into_iter()
            .map(pg_row_to_installed_storage_budget)
            .collect()
    }

