    /// v53.1.5 — `list_attestations_referencing` for a SET of ids (one
    /// `text[]` bind), with the attested / attesting axes the folds pin so
    /// V178's `(attested_key_id, attestation_type, ref)` or V107's attesting
    /// twin serves it as a seek.
    async fn list_composers_referencing_any(
        &self,
        target_attestation_ids: &[String],
        attested_key_id: Option<&str>,
        attesting_key_id: Option<&str>,
    ) -> Result<Vec<crate::federation::Attestation>, crate::federation::Error> {
        if target_attestation_ids.is_empty() {
            return Ok(Vec::new());
        }
        use crate::federation::types::attestation_type;
        let mut params: Vec<Box<dyn tokio_postgres::types::ToSql + Sync + Send>> = vec![
            Box::new(target_attestation_ids.to_vec()),
            Box::new(attestation_type::WITHDRAWS.to_owned()),
            Box::new(attestation_type::RECANTS.to_owned()),
            Box::new(attestation_type::SUPERSEDES.to_owned()),
        ];
        if let Some(k) = attested_key_id {
            params.push(Box::new(k.to_owned()));
        }
        if let Some(k) = attesting_key_id {
            params.push(Box::new(k.to_owned()));
        }
        let sql =
            pg_composers_referencing_any_sql(attested_key_id.is_some(), attesting_key_id.is_some());
        let client = self
            .get_client()
            .await
            .map_err(crate::store::Error::into_federation)?;
        let params_ref: Vec<&(dyn tokio_postgres::types::ToSql + Sync)> =
            params.iter().map(|p| p.as_ref() as _).collect();
        let rows = client.query(&sql, &params_ref[..]).await.map_err(|e| {
            crate::federation::Error::Backend(format!("list_composers_referencing_any: {e}"))
        })?;
        let bytes = pg_envelope_bytes(&rows);
        rows.into_iter()
            .map(pg_row_to_attestation)
            .collect::<Result<Vec<_>, _>>()
            .inspect(|rows| {
                crate::observe::record_read(
                    crate::observe::StoreBackend::Postgres,
                    crate::observe::Door::ListComposersReferencingAny,
                    attested_key_id.or(attesting_key_id).unwrap_or("*"),
                    rows,
                    bytes,
                )
            })
    }

    /// v55.0.0 (CIRISPersist#989) — V190's `(dimension COLLATE "C",
    /// evidence_refs[0])` seek; the expression is spelled as the index is.
    async fn list_attestations_citing_by_dimension(
        &self,
        dimension: &str,
        evidence_ref: &str,
    ) -> Result<Vec<crate::federation::Attestation>, crate::federation::Error> {
        let sql = format!(
            "SELECT {PG_ATTESTATION_COLUMNS} FROM cirislens.federation_attestations \
             WHERE dimension COLLATE \"C\" = $1 \
               AND (attestation_envelope::jsonb->'evidence_refs'->>0) = $2 \
               AND tier = 'federation' \
             ORDER BY asserted_at DESC"
        );
        let client = self
            .get_client()
            .await
            .map_err(crate::store::Error::into_federation)?;
        let rows = client
            .query(&sql, &[&dimension, &evidence_ref])
            .await
            .map_err(|e| {
                crate::federation::Error::Backend(format!(
                    "list_attestations_citing_by_dimension: {e}"
                ))
            })?;
        let bytes = pg_envelope_bytes(&rows);
        rows.into_iter()
            .map(pg_row_to_attestation)
            .collect::<Result<Vec<_>, _>>()
            .inspect(|rows| {
                crate::observe::record_read(
                    crate::observe::StoreBackend::Postgres,
                    crate::observe::Door::ListAttestationsByDimensionCiting,
                    dimension,
                    rows,
                    bytes,
                )
            })
    }

