    async fn dag_manifests_of_chunk(
        &self,
        chunk_sha256: &[u8; 32],
    ) -> Result<Vec<[u8; 32]>, crate::federation::Error> {
        // v53.1.0 (#979) — V176 (chunk → manifest) and V160 (child → root).
        let client = self
            .get_client()
            .await
            .map_err(crate::store::Error::into_federation)?;
        let sha = chunk_sha256.to_vec();
        let rows = client
            .query(
                "SELECT manifest_sha256 AS m FROM cirislens.federation_dag_chunks WHERE chunk_sha256 = $1 \
                 UNION \
                 SELECT root_sha256 AS m FROM cirislens.federation_manifest_children WHERE child_sha256 = $1",
                &[&sha],
            )
            .await
            .map_err(|e| crate::federation::Error::Backend(format!("dag_manifests_of_chunk: {e}")))?;
        rows.iter()
            .map(|r| {
                let v: Vec<u8> = r.safe_get_with("m", crate::federation::Error::Backend)?;
                <[u8; 32]>::try_from(v.as_slice()).map_err(|_| {
                    crate::federation::Error::Backend(
                        "dag_manifests_of_chunk: a 32-byte sha".into(),
                    )
                })
            })
            .collect()
    }

    async fn attestations_binding_content(
        &self,
        content_sha256: &str,
    ) -> Result<Vec<crate::federation::Attestation>, crate::federation::Error> {
        // v8.7.2 (CIRISPersist#233 follow-on, CEG RC27 §11.10) — the
        // content-establishing `scores` rows that bind `content_sha256`
        // in their envelope `evidence_refs` array. `attestation_envelope`
        // is JSONB; the `@>` containment operator does the exact
        // array-membership filter in-engine (`evidence_refs` is a JSON
        // array of hex strings). No new index — the V054 index is on
        // `cirisnode.contributions.media_content_sha256`, a different
        // table; this scan is over `cirislens.federation_attestations`.
        let client = self
            .get_client()
            .await
            .map_err(crate::store::Error::into_federation)?;
        // v47.2.0 (#862) — the pointer shape has no evidence_ref: prefilter on any mention.
        let like = format!("%{content_sha256}%");
        let needle =
            serde_json::Value::Array(vec![serde_json::Value::String(content_sha256.to_owned())]);
        let rows = client
            .query(
                // weight::float8 AS weight — see list_attestations_for.
                "SELECT attestation_id::text, attesting_key_id, attested_key_id, attestation_type, \
                    weight::float8 AS weight, asserted_at, expires_at, attestation_envelope, \
                    original_content_hash, scrub_signature_classical, scrub_signature_pqc, \
                    scrub_key_id, scrub_timestamp, pqc_completed_at, persist_row_hash, subject_key_ids, withdraws_admission_rule, cohort_scope, tier, promoted_at, additional_scrubs \
                 FROM cirislens.federation_attestations \
                 WHERE attestation_type = 'scores' AND tier = 'federation' \
                     AND (attestation_envelope::jsonb -> 'evidence_refs' @> $1 \
                          OR attestation_envelope::text LIKE $2) \
                 ORDER BY asserted_at DESC",
                &[&needle, &like],
            )
            .await
            .map_err(|e| {
                crate::federation::Error::Backend(format!("attestations_binding_content: {e}"))
            })?;
        // v53.0.1 — the SQL above is a PREFILTER (any envelope mentioning the
        // sha). The authoritative check is the shared predicate, as on sqlite
        // and memory: without it a mention was a binding here, and a custody
        // report (which names the sha and binds nothing) kept a withdrawn
        // file Live on postgres.
        let bytes = pg_envelope_bytes(&rows);
        let atts: Vec<crate::federation::Attestation> = rows
            .into_iter()
            .map(pg_row_to_attestation)
            .collect::<Result<_, _>>()?;
        let rows: Vec<crate::federation::Attestation> = atts
            .into_iter()
            .filter(|a| {
                crate::federation::admission::envelope_binds_content(
                    &a.attestation_envelope,
                    content_sha256,
                )
            })
            .collect();
        crate::observe::record_read(
            crate::observe::StoreBackend::Postgres,
            crate::observe::Door::AttestationsBindingContent,
            content_sha256,
            &rows,
            bytes,
        );
        Ok(rows)
    }

    async fn attestations_binding_content_with_placements(
        &self,
        content_sha256: &str,
    ) -> Result<Vec<crate::federation::Attestation>, crate::federation::Error> {
        // v61.4.0 (CIRISPersist#1260) — `attestations_binding_content` plus the
        // `supersedes` placements into a room, in one scan. The same prefilter,
        // then the shared predicate.
        let client = self
            .get_client()
            .await
            .map_err(crate::store::Error::into_federation)?;
        let like = format!("%{content_sha256}%");
        let needle =
            serde_json::Value::Array(vec![serde_json::Value::String(content_sha256.to_owned())]);
        let rows = client
            .query(
                // weight::float8 AS weight — see list_attestations_for.
                "SELECT attestation_id::text, attesting_key_id, attested_key_id, attestation_type, \
                    weight::float8 AS weight, asserted_at, expires_at, attestation_envelope, \
                    original_content_hash, scrub_signature_classical, scrub_signature_pqc, \
                    scrub_key_id, scrub_timestamp, pqc_completed_at, persist_row_hash, subject_key_ids, withdraws_admission_rule, cohort_scope, tier, promoted_at, additional_scrubs \
                 FROM cirislens.federation_attestations \
                 WHERE tier = 'federation' \
                     AND (attestation_type = 'scores' \
                          OR (attestation_type = 'supersedes' \
                              AND cohort_scope IN ('community', 'affiliations'))) \
                     AND (attestation_envelope::jsonb -> 'evidence_refs' @> $1 \
                          OR attestation_envelope::text LIKE $2) \
                 ORDER BY asserted_at DESC",
                &[&needle, &like],
            )
            .await
            .map_err(|e| {
                crate::federation::Error::Backend(format!(
                    "attestations_binding_content_with_placements: {e}"
                ))
            })?;
        let bytes = pg_envelope_bytes(&rows);
        let atts: Vec<crate::federation::Attestation> = rows
            .into_iter()
            .map(pg_row_to_attestation)
            .collect::<Result<_, _>>()?;
        let rows: Vec<crate::federation::Attestation> = atts
            .into_iter()
            .filter(|a| {
                crate::federation::admission::envelope_binds_content(
                    &a.attestation_envelope,
                    content_sha256,
                )
            })
            .collect();
        crate::observe::record_read(
            crate::observe::StoreBackend::Postgres,
            crate::observe::Door::AttestationsBindingContentWithPlacements,
            content_sha256,
            &rows,
            bytes,
        );
        Ok(rows)
    }

