    // v62.0.0 (wave T1; CC 2.7.8) — a merge's tips leave the tip store.
    async fn drop_group_tips(
        &self,
        cohort: crate::federation::cohort::Cohort,
        group_key_id: &str,
        persist_row_hashes: &[String],
    ) -> Result<(), crate::federation::Error> {
        use crate::federation::cohort::Cohort;
        use crate::federation::Error;
        if cohort == Cohort::SelfId {
            return Err(Error::InvalidArgument(
                "drop_group_tips: the `self` cohort is not versioned".to_string(),
            ));
        }
        let cohort_str = cohort.as_str();
        let client = self
            .get_client()
            .await
            .map_err(crate::store::Error::into_federation)?;
        client
            .execute(
                "DELETE FROM cirislens.federation_group_tips \
                 WHERE cohort = $1 AND group_key_id = $2 AND persist_row_hash = ANY($3)",
                &[&cohort_str, &group_key_id, &persist_row_hashes],
            )
            .await
            .map_err(|e| Error::Backend(format!("drop_group_tips: {e}")))?;
        Ok(())
    }

    // #249 Cut G2 (§8) — full version chain: history rows + the live current.
    async fn list_group_versions(
        &self,
        cohort: crate::federation::cohort::Cohort,
        group_key_id: &str,
    ) -> Result<Vec<crate::federation::cohort::GroupVersion>, crate::federation::Error> {
        use crate::federation::cohort::{Cohort, GroupVersion};
        use crate::federation::Error;
        if cohort == Cohort::SelfId {
            return Err(Error::InvalidArgument(
                "list_group_versions: the `self` cohort is not versioned".to_string(),
            ));
        }
        // CC 4.4.3.2.8 / #308: `affiliations` filters its own history chain
        // (`cohort.as_str()`), distinct from `community` though they share the
        // live `federation_communities` row read below.
        let cohort_str = cohort.as_str();
        let client = self
            .get_client()
            .await
            .map_err(crate::store::Error::into_federation)?;
        let rows = client
            .query(
                "SELECT version, snapshot, change_authorization, superseded_at \
                 FROM cirislens.federation_group_versions \
                 WHERE cohort = $1 AND group_key_id = $2 ORDER BY version ASC",
                &[&cohort_str, &group_key_id],
            )
            .await
            .map_err(|e| Error::Backend(format!("list_group_versions: {e}")))?;
        let mut out: Vec<GroupVersion> = Vec::new();
        for r in rows {
            let version: i32 = r.get("version");
            let snapshot: serde_json::Value = r.get("snapshot");
            let authorization: Option<serde_json::Value> = r.get("change_authorization");
            let superseded_at: chrono::DateTime<chrono::Utc> = r.get("superseded_at");
            out.push(GroupVersion {
                cohort,
                group_key_id: group_key_id.to_string(),
                version: version as u32,
                snapshot,
                authorization,
                superseded_at: Some(superseded_at),
                is_current: false,
            });
        }
        let live = if cohort == Cohort::Family {
            client
                .query_opt(
                    "SELECT version, family_key_id, family_name, members, founded_at, \
                            consensus_protocol, consensus_protocol_entrenched, dissolved_at, prev_head_digest, charter_digest, persist_row_hash \
                     FROM cirislens.federation_families WHERE family_key_id = $1",
                    &[&group_key_id],
                )
                .await
                .map_err(|e| Error::Backend(format!("list_group_versions live family: {e}")))?
                .map(|r| {
                    let v: i32 = r.get("version");
                    let fam = pg_row_to_family(r)?;
                    let snap = serde_json::to_value(&fam)
                        .map_err(|e| Error::Backend(format!("live snapshot: {e}")))?;
                    Ok::<_, Error>((v, snap))
                })
                .transpose()?
        } else {
            client
                .query_opt(
                    "SELECT version, community_key_id, community_name, members, founded_at, \
                            consensus_protocol, policy_blob, prev_head_digest, charter_digest, persist_row_hash \
                     FROM cirislens.federation_communities WHERE community_key_id = $1",
                    &[&group_key_id],
                )
                .await
                .map_err(|e| Error::Backend(format!("list_group_versions live community: {e}")))?
                .map(|r| {
                    let v: i32 = r.get("version");
                    let comm = pg_row_to_community(r)?;
                    let snap = serde_json::to_value(&comm)
                        .map_err(|e| Error::Backend(format!("live snapshot: {e}")))?;
                    Ok::<_, Error>((v, snap))
                })
                .transpose()?
        };
        if let Some((version, snapshot)) = live {
            out.push(GroupVersion {
                cohort,
                group_key_id: group_key_id.to_string(),
                version: version as u32,
                snapshot,
                authorization: None,
                superseded_at: None,
                is_current: true,
            });
        }
        out.sort_by_key(|v| v.version);
        Ok(out)
    }

    /// v62.0.0 (kernel pass 2, K1, I2812) — the versions held as tips.
    async fn list_group_tips(
        &self,
        cohort: crate::federation::cohort::Cohort,
        group_key_id: &str,
    ) -> Result<Vec<crate::federation::cohort::GroupTip>, crate::federation::Error> {
        use crate::federation::cohort::{Cohort, GroupTip};
        use crate::federation::Error;
        if cohort == Cohort::SelfId {
            return Err(Error::InvalidArgument(
                "list_group_tips: the `self` cohort is not versioned".to_string(),
            ));
        }
        let cohort_str = cohort.as_str();
        let client = self
            .get_client()
            .await
            .map_err(crate::store::Error::into_federation)?;
        let rows = client
            .query(
                "SELECT persist_row_hash, prev_head_digest, snapshot, change_authorization, \
                        held_at \
                 FROM cirislens.federation_group_tips \
                 WHERE cohort = $1 AND group_key_id = $2 \
                 ORDER BY held_at ASC, persist_row_hash ASC",
                &[&cohort_str, &group_key_id],
            )
            .await
            .map_err(|e| Error::Backend(format!("list_group_tips: {e}")))?;
        let mut out = Vec::with_capacity(rows.len());
        for r in rows {
            out.push(GroupTip {
                cohort: cohort_str.to_owned(),
                group_key_id: group_key_id.to_owned(),
                persist_row_hash: r.safe_get_with("persist_row_hash", Error::Backend)?,
                prev_head_digest: r.safe_get_with("prev_head_digest", Error::Backend)?,
                snapshot: r.safe_get_with("snapshot", Error::Backend)?,
                change_authorization: r.safe_get_with("change_authorization", Error::Backend)?,
                held_at: r.safe_get_with("held_at", Error::Backend)?,
            });
        }
        Ok(out)
    }

