    // ─── v4.8.0 (CIRISPersist#161, CEG §11.7.1) — membership revocations.

    // v62.0.0 (WD-fix8) — the edition-2 eviction's STORE (the retired
    // trusted-local verb `put_identity_occurrence_revocation_local` refuses
    // by name, the trait default).
    async fn put_identity_occurrence_revocation_edition2(
        &self,
        revocation: crate::federation::IdentityOccurrenceRevocation,
        _door: crate::federation::DoorToken,
    ) -> Result<(), crate::federation::Error> {
        // #421 — trusted-local (grandfathered) write: NO signature gate, signed
        // columns NULL. Mirrors `put_identity_occurrence_local`.
        let mut row = revocation;
        row.persist_row_hash = crate::federation::types::compute_persist_row_hash(&row)?;
        let witness = serde_json::json!(row.witness_set);
        let client = self
            .get_client()
            .await
            .map_err(crate::store::Error::into_federation)?;
        // v36.0.0 (#668) — THIS node's serve position (V130).
        let admitted_at = self
            .next_plane_position(&client, "federation_identity_occurrence_revocations")
            .await?;
        client
            .execute(
                "INSERT INTO cirislens.federation_identity_occurrence_revocations (\
                    identity_key_id, occurrence_key_id, revoked_at, effective_at, \
                    reason, witness_set, persist_row_hash, admitted_at\
                 ) VALUES ($1, $2, $3, $4, $5, $6, $7, $8)",
                &[
                    &row.identity_key_id,
                    &row.occurrence_key_id,
                    &row.revoked_at,
                    &row.effective_at,
                    &row.reason,
                    &witness,
                    &row.persist_row_hash,
                    &admitted_at,
                ],
            )
            .await
            .map_err(map_revocation_pg_err(
                "identity_occurrence_revocation",
                &[row.identity_key_id.as_str(), row.occurrence_key_id.as_str()],
            ))?;
        // #446 de-projection — mirrors the signed revocation path.
        // v36.0.0 (#668/#707-class) — the retirement moves the route's serve
        // position; see the signed twin.
        let route_admitted_at = self
            .next_plane_position(&client, "transport_destinations")
            .await?;
        client
            .execute(
                "UPDATE cirislens.transport_destinations SET retired_at = $1, admitted_at = $4 \
                 WHERE occurrence_key_id = $2 AND transport_kind = $3 \
                   AND signature IS NULL AND retired_at IS NULL",
                &[
                    &row.revoked_at,
                    &row.occurrence_key_id,
                    &crate::federation::types::OccurrenceTransportBinding::TRANSPORT_KIND,
                    &route_admitted_at,
                ],
            )
            .await
            .map_err(map_revocation_pg_err(
                "identity_occurrence_revocation",
                &[row.identity_key_id.as_str(), row.occurrence_key_id.as_str()],
            ))?;
        Ok(())
    }

