    async fn communities_containing(
        &self,
        cell_id: &str,
    ) -> Result<Vec<crate::federation::Community>, crate::federation::Error> {
        // Prefilter to geographic communities (JSONB), h3-filter in Rust.
        let client = self
            .get_client()
            .await
            .map_err(crate::store::Error::into_federation)?;
        let rows = client
            .query(
                "SELECT community_key_id, community_name, members, founded_at, \
                    consensus_protocol, policy_blob, prev_head_digest, charter_digest, persist_row_hash \
                 FROM cirislens.federation_communities \
                 WHERE policy_blob->>'cohort_subkind' = 'geographic' \
                 ORDER BY community_key_id ASC",
                &[],
            )
            .await
            .map_err(|e| {
                crate::federation::Error::Backend(format!("communities_containing: {e}"))
            })?;
        let all: Vec<crate::federation::Community> = rows
            .into_iter()
            .map(pg_row_to_community)
            .collect::<Result<_, _>>()?;
        Ok(all
            .into_iter()
            .filter(|c| {
                crate::federation::location::geographic_constraint_cell(c.policy_blob.as_ref())
                    .is_some_and(|constraint| {
                        crate::federation::location::h3_cell_contained(cell_id, &constraint)
                    })
            })
            .collect())
    }

    // ─── v21.0.0 (CIRISPersist#504 FLOOR) — bulk signed-since reads for the
    //     5 E4 keyless-declaration planes (edge advertise/serve bridge).
    //     Signed-only: `authority_key_id IS NOT NULL AND authority_key_id <>
    //     ''` excludes `put_family_local` genesis-bake (and any other
    //     legitimately-unsigned) rows — serving one would hand the edge
    //     responder empty signature bytes.

    async fn list_signed_families_since(
        &self,
        since: Option<(chrono::DateTime<chrono::Utc>, String)>,
        limit: u32,
    ) -> Result<Vec<crate::federation::ServedFamily>, crate::federation::Error> {
        let client = self
            .get_client()
            .await
            .map_err(crate::store::Error::into_federation)?;
        let limit = i64::from(limit);
        let since_at = since.as_ref().map(|(t, _)| *t);
        let since_id = since.as_ref().map(|(_, id)| id.clone());
        let rows = client
            .query(
                "SELECT * FROM cirislens.federation_families \
                 WHERE ($1::timestamptz IS NULL OR (admitted_at, family_key_id) > ($1, $2)) \
                   AND authority_key_id IS NOT NULL AND authority_key_id <> '' \
                 ORDER BY admitted_at ASC, family_key_id ASC LIMIT $3",
                &[&since_at, &since_id, &limit],
            )
            .await
            .map_err(|e| {
                crate::federation::Error::Backend(format!("list_signed_families_since: {e}"))
            })?;
        rows.into_iter()
            .map(|row| {
                let admitted_at =
                    row.safe_get_with("admitted_at", crate::federation::Error::Backend)?;
                Ok(crate::federation::ServedFamily {
                    family: pg_row_to_signed_family(row)?,
                    admitted_at,
                })
            })
            .collect()
    }

