    // ─── v21.1.0 (CIRISPersist#507c) — bulk signed-since reads for the 5
    //     PRIMARY signed planes.

    /// v31.1.0 (CIRISPersist#662) — the signed accord EVIDENCE cursor. `limit`
    /// pages PROPOSALS; the participation set for each is assembled by the
    /// shared
    /// [`accord_carriage::assemble_evidence_page`](crate::federation::accord_carriage::assemble_evidence_page),
    /// which owns the `member_id` sort so all three backends serialize alike.
    async fn list_signed_accord_quorum_evidence_since(
        &self,
        since: Option<(chrono::DateTime<chrono::Utc>, String)>,
        limit: u32,
    ) -> Result<
        Vec<crate::federation::accord_carriage::AccordQuorumEvidence>,
        crate::federation::Error,
    > {
        let client = self
            .get_client()
            .await
            .map_err(crate::store::Error::into_federation)?;
        let limit_i = i64::from(limit);
        let since_at = since.as_ref().map(|(t, _)| *t);
        let since_id = since.as_ref().map(|(_, id)| id.clone());
        let rows = client
            .query(
                // v31.1.0 (CIRISPersist#662, PR review P1) — the cursor is the
                // bundle's VISIBILITY instant, not the proposal's immutable
                // `created_at`: a vote landing must move the bundle forward in
                // the stream, or a peer that read it pre-quorum never sees the
                // version that carries one.
                // v31.1.0 (PR review P1) — `evidence_at` is SELECTED and
                // carried out with the row, never recomputed at assembly time:
                // a vote landing in between would otherwise return an instant
                // later than the one the page was chosen with, and a consumer
                // resuming from it would skip the proposals cut by `LIMIT` in
                // that gap.
                // v36.0.0 (#668) — resumed on the (evidence_at,
                // proposal_digest) PAIR: two proposals whose latest vote landed
                // in one instant tie, and resumed on the instant alone a page
                // ending mid-tie lost the remainder.
                "SELECT proposal_json, authority_signature, persist_row_hash, created_at, \
                        evidence_at \
                 FROM ( \
                   SELECT proposal_json, authority_signature, persist_row_hash, created_at, \
                          proposal_digest, \
                          GREATEST(created_at, COALESCE(( \
                              SELECT MAX(server_arrival_at) \
                              FROM cirislens.accord_participation ap \
                              WHERE ap.proposal_digest = p.proposal_digest \
                          ), created_at)) AS evidence_at \
                   FROM cirislens.accord_proposal p \
                 ) AS bundles \
                 WHERE ($1::timestamptz IS NULL OR \
                        (evidence_at, proposal_digest) > ($1, $2)) \
                 ORDER BY evidence_at ASC, proposal_digest ASC LIMIT $3",
                &[&since_at, &since_id, &limit_i],
            )
            .await
            .map_err(|e| {
                crate::federation::Error::Backend(format!(
                    "list_signed_accord_quorum_evidence_since: {e}"
                ))
            })?;
        let mut page = Vec::with_capacity(rows.len());
        for row in rows {
            let evidence_at: chrono::DateTime<chrono::Utc> = row
                .try_get("evidence_at")
                .map_err(|e| crate::federation::Error::Backend(format!("evidence_at: {e}")))?;
            page.push((pg_row_to_stored_proposal(row)?, evidence_at));
        }
        // v59.1.2 — assembly reads each proposal's participations through
        // the directory (its own clients).
        drop(client);
        crate::federation::accord_carriage::assemble_evidence_page(self, page).await
    }

    /// v31.1.0 (CIRISPersist#662) — delegates to the shared re-tally body.
    async fn apply_replicated_accord_evidence(
        &self,
        evidence: &crate::federation::accord_carriage::AccordQuorumEvidence,
    ) -> Result<crate::federation::accord_carriage::AccordEvidenceAdmission, crate::federation::Error>
    {
        crate::federation::accord_carriage::admit_replicated_accord_evidence(self, evidence).await
    }

    async fn list_signed_transport_destinations_since(
        &self,
        since: Option<(chrono::DateTime<chrono::Utc>, String)>,
        limit: u32,
    ) -> Result<Vec<crate::federation::ServedTransportDestination>, crate::federation::Error> {
        let client = self
            .get_client()
            .await
            .map_err(crate::store::Error::into_federation)?;
        let limit = i64::from(limit);
        let since_at = since.as_ref().map(|(t, _)| *t);
        let (since_a, since_b) = match since.as_ref() {
            Some((_, id)) => {
                let [a, b] = crate::federation::types::split_resume_id::<2>(id);
                (Some(a.to_owned()), Some(b.to_owned()))
            }
            None => (None, None),
        };
        // Signed-put rows only; RETIRED rows ARE included — tombstones
        // must gossip, matching `list_signed_transport_destinations_for` —
        // and v36.0.0 (#668) the retire doors MOVE the serve position.
        let rows = client
            .query(
                "SELECT occurrence_key_id, transport_kind, destination, asserted_at, last_seen_at, \
                    transport_ed25519_pubkey_base64, transport_x25519_pubkey_base64, \
                    binding_provenance, epoch, retired_at, \
                    attesting_key_id, signed_envelope, signature, admitted_at \
                 FROM cirislens.transport_destinations \
                 WHERE ($1::timestamptz IS NULL OR \
                        (admitted_at, occurrence_key_id, transport_kind) > ($1, $2, $3)) \
                   AND attesting_key_id IS NOT NULL \
                   AND signed_envelope IS NOT NULL \
                   AND signature IS NOT NULL \
                 ORDER BY admitted_at ASC, occurrence_key_id ASC, transport_kind ASC \
                 LIMIT $4",
                &[&since_at, &since_a, &since_b, &limit],
            )
            .await
            .map_err(|e| {
                crate::federation::Error::Backend(format!(
                    "list_signed_transport_destinations_since: {e}"
                ))
            })?;
        rows.iter()
            .map(|row| {
                let admitted_at =
                    row.safe_get_with("admitted_at", crate::federation::Error::Backend)?;
                Ok(crate::federation::ServedTransportDestination {
                    destination: pg_row_to_signed_transport_destination(row)?,
                    admitted_at,
                })
            })
            .collect()
    }

    async fn attestation_type_census(
        &self,
    ) -> Result<Vec<crate::federation::row_type::AttestationTypeCount>, crate::federation::Error>
    {
        let client = self
            .get_client()
            .await
            .map_err(crate::store::Error::into_federation)?;
        let rows = client
            .query(
                "SELECT attestation_type, COUNT(*)::int8, MIN(asserted_at), MAX(asserted_at) \
                   FROM cirislens.federation_attestations GROUP BY attestation_type \
                  ORDER BY attestation_type",
                &[],
            )
            .await
            .map_err(|e| {
                crate::federation::Error::Backend(format!("attestation_type_census: {e}"))
            })?;
        rows.into_iter()
            .map(|r| {
                let count: i64 = r.try_get(1).map_err(|e| {
                    crate::federation::Error::Backend(format!("attestation_type_census: {e}"))
                })?;
                let get =
                    |i: usize| -> Result<chrono::DateTime<chrono::Utc>, crate::federation::Error> {
                        r.try_get(i).map_err(|e| {
                            crate::federation::Error::Backend(format!(
                                "attestation_type_census: {e}"
                            ))
                        })
                    };
                Ok(crate::federation::row_type::AttestationTypeCount {
                    attestation_type: r.try_get(0).map_err(|e| {
                        crate::federation::Error::Backend(format!("attestation_type_census: {e}"))
                    })?,
                    count: u64::try_from(count).unwrap_or(0),
                    oldest: get(2)?,
                    newest: get(3)?,
                })
            })
            .collect()
    }

    async fn list_attestations_since(
        &self,
        since: Option<(chrono::DateTime<chrono::Utc>, String)>,
        limit: u32,
    ) -> Result<Vec<crate::federation::ServedAttestation>, crate::federation::Error> {
        let client = self
            .get_client()
            .await
            .map_err(crate::store::Error::into_federation)?;
        let limit = i64::from(limit);
        let since_at = since.as_ref().map(|(t, _)| *t);
        let since_id = since.as_ref().map(|(_, id)| id.clone());
        // v61.1.0 (review D3) — THE serve rule (`read_plan::serve_rule_parts`):
        // E5, the federation tier only (a local-tier row never reaches the
        // advertise/serve wire surface); v53.0.0 (#975, CC 2.4), under
        // enforcement a held row of an unregistered type is neither served
        // nor replicated; v54.1.0 (#1046), a tombstoned row is not served
        // unless the tombstone is void for it (the accountability record, a
        // person-subject row: Codex rounds 1 and 4 on PR #1057). Excluded in
        // the SQL, before the page is cut.
        // v62.0.0 (RL-fix2b; CC 5.3.4) — this node's standing, asked once:
        // a node that is not rooted excludes the federation-tier rows that
        // wait, in the SQL, before the page is cut.
        let rooted = crate::federation::edition2::serve::rooted_for_serve(self).await?;
        let serve_rule = crate::federation::read_plan::serve_rule_parts(
            crate::federation::attestation_query::Dialect::Postgres,
            "fa",
            "cirislens.",
            rooted,
        )
        .join(" AND ");
        let rows = client
            .query(
                &format!(
                    "SELECT attestation_id::text, attesting_key_id, attested_key_id, \
                        attestation_type, \
                        weight::float8 AS weight, asserted_at, expires_at, attestation_envelope, \
                        original_content_hash, scrub_signature_classical, scrub_signature_pqc, \
                        scrub_key_id, scrub_timestamp, pqc_completed_at, persist_row_hash, \
                        subject_key_ids, withdraws_admission_rule, cohort_scope, tier, \
                        promoted_at, additional_scrubs, admitted_at \
                     FROM cirislens.federation_attestations fa \
                     WHERE ($1::timestamptz IS NULL OR \
                            (admitted_at, attestation_id::text) > ($1, $2)) \
                       AND {serve_rule} \
                     ORDER BY admitted_at ASC, attestation_id ASC LIMIT $3"
                ),
                &[&since_at, &since_id, &limit],
            )
            .await
            .map_err(|e| {
                crate::federation::Error::Backend(format!("list_attestations_since: {e}"))
            })?;
        let bytes = pg_envelope_bytes(&rows);
        rows.into_iter()
            .map(|row| {
                let admitted_at =
                    row.safe_get_with("admitted_at", crate::federation::Error::Backend)?;
                Ok(crate::federation::ServedAttestation {
                    attestation: pg_row_to_attestation(row)?,
                    admitted_at,
                })
            })
            .collect::<Result<Vec<_>, _>>()
            .inspect(|rows| {
                crate::observe::record_read(
                    crate::observe::StoreBackend::Postgres,
                    crate::observe::Door::ListAttestationsSince,
                    "*",
                    rows,
                    bytes,
                )
            })
    }

    // ─── v21.1.0 (CIRISPersist#507b) — the shared signed-wire content-hash
    //     index (V111 `signed_wire_index`).

    async fn lookup_signed_record_by_content_hash(
        &self,
        kind: &str,
        content_hash: &str,
    ) -> Result<Option<Vec<u8>>, crate::federation::Error> {
        // v62.0.0 (JSON-cut slice B) — a statement by its statement id, a row
        // by its row id: the bytes as received.
        if let Some(served) =
            crate::federation::edition2::store::lookup_by_id(self, kind, content_hash).await?
        {
            return Ok(served);
        }
        let client = self
            .get_client()
            .await
            .map_err(crate::store::Error::into_federation)?;
        let row_opt = client
            .query_opt(
                "SELECT record_key FROM cirislens.signed_wire_index \
                 WHERE kind = $1 AND content_hash = $2",
                &[&kind, &content_hash],
            )
            .await
            .map_err(|e| {
                crate::federation::Error::Backend(format!("signed_wire_index lookup: {e}"))
            })?;
        let Some(row) = row_opt else {
            return Ok(None);
        };
        let record_key: String =
            row.safe_get_with("record_key", crate::federation::Error::Backend)?;
        // v59.1.2 — the reload reads through the directory (its own clients).
        drop(client);
        // v62.0.0 (TB2-prod2; #934) — the reload, the hash self-heal and the
        // rootless serve wait are the SHARED plan; this door keeps its read.
        crate::federation::wire_index::point_read_planned(self, kind, content_hash, &record_key)
            .await
    }

    async fn rebuild_signed_wire_index(&self) -> Result<u64, crate::federation::Error> {
        let triples = crate::federation::wire_index::all_kind_hash_keys(self).await?;
        let client = self
            .get_client()
            .await
            .map_err(crate::store::Error::into_federation)?;
        for (kind, hash, record_key) in &triples {
            pg_upsert_wire_index(&**client, kind, hash, record_key).await?;
        }
        Ok(triples.len() as u64)
    }

    async fn get_attestation(
        &self,
        attestation_id: &str,
    ) -> Result<Option<crate::federation::Attestation>, crate::federation::Error> {
        let client = self
            .get_client()
            .await
            .map_err(crate::store::Error::into_federation)?;
        // Parse attestation_id to uuid::Uuid before binding — the driver
        // refuses to serialize a &str against a `uuid`-typed param (see
        // put_revocation / the 1693 comment). Invalid → no such row.
        // v30.6.0 (CIRISPersist#622) — this was the WORST of the nine: a
        // non-UUID id did not error, it returned `Ok(None)`. So
        // `get_attestation("genesis-charter")` answered "no such row" on
        // Postgres and returned the row on SQLite — a silent divergence, not a
        // refusal. Bound as TEXT now; there is nothing left to fail to parse.
        let row_opt = client
            .query_opt(
                "SELECT attestation_id::text, attesting_key_id, attested_key_id, attestation_type, \
                    weight::float8 AS weight, asserted_at, expires_at, attestation_envelope, \
                    original_content_hash, scrub_signature_classical, scrub_signature_pqc, \
                    scrub_key_id, scrub_timestamp, pqc_completed_at, persist_row_hash, subject_key_ids, withdraws_admission_rule, cohort_scope, tier, promoted_at, additional_scrubs \
                 FROM cirislens.federation_attestations WHERE attestation_id = $1",
                &[&attestation_id],
            )
            .await
            .map_err(|e| crate::federation::Error::Backend(format!("get_attestation: {e}")))?;
        let bytes = pg_envelope_bytes(row_opt.as_slice());
        row_opt
            .map(pg_row_to_attestation)
            .transpose()
            .inspect(|row| {
                crate::observe::record_read(
                    crate::observe::StoreBackend::Postgres,
                    crate::observe::Door::GetAttestation,
                    attestation_id,
                    row.as_slice(),
                    bytes,
                )
            })
    }

    /// v39.0.0 — the tier crossing. Everything that decides lives in
    /// `crossing::plan_enter_mesh` (read that module's doc); this method
    /// executes the plan in ONE statement guarded by `tier = 'local'`, re-stamps
    /// the plane position (v36.0.0 #668: the crossing IS this plane's admission
    /// into the federation stream, so `admitted_at` is the cursor key), refreshes
    /// the `attestation_subjects` projection (V106) and re-indexes the row under
    /// its stored bytes (#507b/#646). Nothing in the signed bytes changes.
    async fn enter_mesh(
        &self,
        attestation_id: &str,
        ci: &crate::federation::ContextualIntegrity,
        custody: &crate::federation::TierPromotionCustody,
    ) -> Result<crate::federation::MeshCrossingOutcome, crate::federation::Error> {
        use crate::federation::{crossing, Error, MeshCrossingOutcome};
        let current = self.get_attestation(attestation_id).await?.ok_or_else(|| {
            Error::InvalidArgument(format!(
                "federation_attestations row {attestation_id} does not exist"
            ))
        })?;
        let Some(crossing::EnterPlan { row, crossing }) =
            crossing::plan_enter_mesh(self, &current, ci, custody, self.self_key_id().as_deref())
                .await?
        else {
            return Ok(MeshCrossingOutcome::AlreadyInMesh {
                attestation_id: attestation_id.to_owned(),
            });
        };
        let och: Vec<u8> = hex::decode(&row.original_content_hash)
            .map_err(|e| Error::Backend(format!("original_content_hash hex: {e}")))?;
        // v31.0.0 (#644) — attestation_envelope is TEXT since V122.
        let attestation_envelope_text =
            pg_envelope_text(&row.attestation_envelope, "attestation_envelope")?;
        let additional_scrubs_json = serde_json::to_string(&row.additional_scrubs)
            .map_err(|e| Error::Backend(format!("additional_scrubs serialize: {e}")))?;
        let mut client = self
            .get_client()
            .await
            .map_err(crate::store::Error::into_federation)?;
        let admitted_at = self
            .next_plane_position(&client, "federation_attestations")
            .await?;
        let tx = client
            .transaction()
            .await
            .map_err(|e| Error::Backend(format!("enter_mesh transaction: {e}")))?;
        let n = tx
            .execute(
                "UPDATE cirislens.federation_attestations \
                 SET attestation_envelope = $1, original_content_hash = $2, \
                     scrub_signature_classical = $3, scrub_signature_pqc = $4, \
                     scrub_key_id = $5, scrub_timestamp = $6, pqc_completed_at = $7, \
                     persist_row_hash = $8, tier = 'federation', promoted_at = $9, \
                     additional_scrubs = $10, admitted_at = $11 \
                 WHERE attestation_id = $12 AND tier = 'local'",
                &[
                    &attestation_envelope_text,
                    &och,
                    &row.scrub_signature_classical,
                    &row.scrub_signature_pqc,
                    &row.scrub_key_id,
                    &row.scrub_timestamp,
                    &row.pqc_completed_at,
                    &row.persist_row_hash,
                    &row.promoted_at,
                    &additional_scrubs_json,
                    &admitted_at,
                    &attestation_id,
                ],
            )
            .await
            .map_err(|e| Error::Backend(format!("enter_mesh: {e}")))?;
        if n == 0 {
            return Err(Error::Conflict(format!(
                "federation_attestations row {attestation_id} was concurrently promoted"
            )));
        }
        tx.execute(
            "UPDATE cirislens.attestation_subjects SET tier = 'federation' \
             WHERE attestation_id = $1",
            &[&attestation_id],
        )
        .await
        .map_err(|e| Error::Backend(format!("enter_mesh projection: {e}")))?;
        // v62.0.0 (v62 P8) — an edition-2 row's statements move to this
        // node's next serve position with the crossing, in the same
        // transaction (`edition2::store::restamp_row_sqlite`'s reason).
        crate::federation::edition2::store::restamp_row_postgres(&tx, attestation_id)
            .await
            .map_err(|e| Error::Backend(format!("enter_mesh statement position: {e}")))?;
        tx.commit()
            .await
            .map_err(|e| Error::Backend(format!("enter_mesh commit: {e}")))?;
        let wire_index_key =
            crate::federation::wire_index::record_key(&[("attestation_id", &row.attestation_id)]);
        drop(client);
        self.index_stored_record("Attestation", &wire_index_key)
            .await?;
        Ok(MeshCrossingOutcome::Crossed(crossing))
    }

