    /// §H round-trip: insert 3 scrubbed traces (1 Generic, 2 Detailed)
    /// + 1 unscrubbed; assert envelopes_scrubbed=3 and by_trace_level
    /// reflects the levels.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn read_section_h_aggregate_scrub_stats_round_trip() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        use crate::read::ReadEngine;

        let aid = format!("agent-§h-{}", uuid_like());
        let base = chrono::Utc::now() - chrono::Duration::hours(1);
        let until = chrono::Utc::now() + chrono::Duration::minutes(1);
        let window =
            crate::read::TimeWindow::new(base - chrono::Duration::minutes(1), until).unwrap();

        insert_section_h_fixture_scrubbed_trace(
            &backend,
            &format!("tr-h-g-{}", uuid_like()),
            &aid,
            base,
            true,
            crate::schema::TraceLevel::Generic,
        )
        .await;
        insert_section_h_fixture_scrubbed_trace(
            &backend,
            &format!("tr-h-d1-{}", uuid_like()),
            &aid,
            base + chrono::Duration::minutes(1),
            true,
            crate::schema::TraceLevel::Detailed,
        )
        .await;
        insert_section_h_fixture_scrubbed_trace(
            &backend,
            &format!("tr-h-d2-{}", uuid_like()),
            &aid,
            base + chrono::Duration::minutes(2),
            true,
            crate::schema::TraceLevel::Detailed,
        )
        .await;
        insert_section_h_fixture_scrubbed_trace(
            &backend,
            &format!("tr-h-u-{}", uuid_like()),
            &aid,
            base + chrono::Duration::minutes(3),
            false,
            crate::schema::TraceLevel::Generic,
        )
        .await;

        // Note: aggregate_scrub_stats(window) doesn't filter by agent —
        // it's a global window aggregate. So we need to assert "at least
        // these counts", not "exactly these counts" (other tests may
        // share the window). Tighten by clamping the window to just our
        // fixture range.
        let agg = backend
            .aggregate_scrub_stats(window, crate::scope::CallerScope::Unauthenticated)
            .await
            .unwrap();
        assert!(
            agg.envelopes_scrubbed >= 3,
            "at least 3 scrubbed; got {}",
            agg.envelopes_scrubbed
        );
        assert!(
            agg.by_trace_level
                .get(&crate::schema::TraceLevel::Detailed)
                .copied()
                .unwrap_or(0)
                >= 2
        );
        assert!(
            agg.by_trace_level
                .get(&crate::schema::TraceLevel::Generic)
                .copied()
                .unwrap_or(0)
                >= 1
        );

        // v0.5.5 limitations: until v0.6.0 ships the classification
        // pipeline, these MUST be 0/empty.
        assert_eq!(agg.fields_scrubbed_total, 0);
        assert!(agg.by_entity_type.is_empty());
    }

    /// §H empty window: zeroes + empty maps.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn read_section_h_aggregate_scrub_stats_empty_window() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        use crate::read::ReadEngine;

        let since = chrono::Utc::now() + chrono::Duration::days(365);
        let until = since + chrono::Duration::hours(1);
        let window = crate::read::TimeWindow::new(since, until).unwrap();
        let agg = backend
            .aggregate_scrub_stats(window, crate::scope::CallerScope::Unauthenticated)
            .await
            .unwrap();
        assert_eq!(agg.envelopes_scrubbed, 0);
        assert_eq!(agg.fields_scrubbed_total, 0);
        assert!(agg.by_entity_type.is_empty());
        assert!(agg.by_trace_level.is_empty());
    }

    // ─── ReadEngine §I tests (v0.5.5, CIRISPersist#23) ──────────────

    // ─── v31.4.0 (CIRISPersist#682 / #668) — the identity plane's serve
    //     cursor, postgres arm. Assertion bodies shared with the memory and
    //     sqlite arms; only the PLANT is backend-specific.
    //
    //     Each runs in an ISOLATED database. The cursor assertions are about
    //     what a full page contains and how many rows a tie holds, so a shared
    //     database's leftover `federation_keys` rows would make them measure
    //     the fixture instead of the fix.

    /// Build a federation KeyRecord with controllable valid_from /
    /// pqc_completed.
    /// v62.0.0 (the JSON cut) — the `federation_keys` read model of an
    /// edition-2 `agent` key `key_id` (a seed), valid from `valid_from`. Make
    /// it live with `e2::put_key_row`. `identity_ref` and `pqc_completed` are
    /// earlier-form (an edition-2 key's identity-ref IS its kid, and a
    /// composite signature is atomic); kept in the signature so call sites
    /// stay put.
    /// The earlier-form record `fix_section_i_key` returned before v62, for
    /// the typed-plane tests HELD under the earlier form
    /// (`e2::with_earlier_form_async`, the lead's ruling) until their planes
    /// get edition-2 projections.
    fn pg_earlier_key(
        key_id: &str,
        identity_ref: &str,
        valid_from: chrono::DateTime<chrono::Utc>,
        pqc_completed: bool,
    ) -> crate::federation::KeyRecord {
        let (ed_pk, mldsa_pk) =
            crate::federation::tier_ingest::test_support::hybrid_pubkeys(key_id);
        crate::federation::KeyRecord {
            key_id: key_id.into(),
            pubkey_ed25519_base64: ed_pk,
            pubkey_ml_dsa_65_base64: mldsa_pk,
            algorithm: crate::federation::types::algorithm::HYBRID.into(),
            identity_type: crate::federation::types::identity_type::AGENT.into(),
            identity_ref: identity_ref.into(),
            valid_from,
            valid_until: None,
            registration_envelope: serde_json::json!({"id": key_id}),
            original_content_hash: "deadbeef".into(),
            scrub_signature_classical: "c2lnbmF0dXJl".into(),
            scrub_signature_pqc: if pqc_completed {
                Some("c2ln".into())
            } else {
                None
            },
            scrub_key_id: key_id.into(),
            scrub_timestamp: valid_from,
            pqc_completed_at: if pqc_completed {
                Some(valid_from)
            } else {
                None
            },
            persist_row_hash: String::new(),
            capability_roles: Vec::new(),
            // v47.3.0 (#901, FSD §3.6) — every synthetic identity is hardware-attested.
            attestation_evidence: Some(
                crate::federation::hardware_attestation::test_support::fresh_accord_holder_evidence(
                ),
            ),
            consent_role: None,
            additional_scrubs: Vec::new(),
        }
    }

    fn fix_section_i_key(
        key_id: &str,
        identity_ref: &str,
        valid_from: chrono::DateTime<chrono::Utc>,
        pqc_completed: bool,
    ) -> crate::federation::KeyRecord {
        if !e2::emit_edition2() {
            return pg_earlier_key(key_id, identity_ref, valid_from, pqc_completed);
        }
        e2::key_row_with(
            key_id,
            &[crate::federation::types::identity_type::AGENT],
            &e2::KeyRecordOptions {
                valid_from_ms: u64::try_from(valid_from.timestamp_millis()).ok(),
                ..Default::default()
            },
        )
    }

    /// v13.0.0 (CIRISPersist#365, CC 3.4.7.2) — consent_role round-trips
    /// through put/lookup, OQ-1 overwrite-on-revoke via set_consent_role,
    /// and the consent_role_of resolver — on the Postgres twin. Gated on a
    /// live test PG (skips when `CIRIS_PERSIST_TEST_PG_URL` is unset).
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn consent_role_round_trip_overwrite_and_resolver_pg() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        use crate::federation::consent::consent_role_of;
        use crate::federation::types::consent_role;
        use crate::federation::FederationDirectory;
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        let now = chrono::Utc::now();
        let kid = format!("k-cr-{}", uuid_like());

        // v62.0.0: an edition-2 `key:record` carries no consent role, so the
        // key is registered, then given `peer` through the setter, and
        // round-trips. Named by its kid from here on.
        let _ = now;
        let kid = pg_put_key(
            &backend,
            &kid,
            crate::federation::types::identity_type::AGENT,
        )
        .await;
        FederationDirectory::set_consent_role(&backend, &kid, Some(consent_role::PEER))
            .await
            .unwrap();
        let got = FederationDirectory::lookup_public_key(&backend, &pg_id(&kid))
            .await
            .unwrap()
            .unwrap();
        assert_eq!(got.consent_role.as_deref(), Some(consent_role::PEER));
        assert_eq!(
            consent_role_of(&backend, &kid).await.unwrap().as_deref(),
            Some(consent_role::PEER)
        );

        // OQ-1 overwrite → authorized_review.
        FederationDirectory::set_consent_role(
            &backend,
            &kid,
            Some(consent_role::AUTHORIZED_REVIEW),
        )
        .await
        .unwrap();
        assert_eq!(
            consent_role_of(&backend, &kid).await.unwrap().as_deref(),
            Some(consent_role::AUTHORIZED_REVIEW)
        );

        // Revoke (overwrite to None).
        FederationDirectory::set_consent_role(&backend, &kid, None)
            .await
            .unwrap();
        assert_eq!(consent_role_of(&backend, &kid).await.unwrap(), None);

        // Unknown key: setter errors, resolver stays total.
        let missing = format!("k-cr-missing-{}", uuid_like());
        assert!(
            FederationDirectory::set_consent_role(&backend, &missing, Some("peer"))
                .await
                .is_err()
        );
        assert_eq!(consent_role_of(&backend, &missing).await.unwrap(), None);
    }

    /// V060 community substrate round-trip on Postgres — parity with
    /// the sqlite `community_round_trip` test. Gated on a live test PG
    /// (skips when `CIRIS_PERSIST_TEST_PG_URL` is unset), same as every
    /// other postgres test.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn community_round_trip_pg() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        use crate::federation::FederationDirectory;

        let now = chrono::Utc::now();
        let suffix = uuid_like();
        let coop = format!("acme-coop-{suffix}");
        let alice = format!("alice-root-{suffix}");
        let bob = format!("bob-root-{suffix}");
        let carol = format!("carol-root-{suffix}");
        // The community key itself is infra-class; the `*-root` members are
        // user-role human identities (trivially steward-bound — the v9.0.0
        // CC 3.2 / CC 3.4.7.1 non-infra membership precondition).
        pg_put_key_rec(&backend, &fix_section_i_key(&coop, "acme", now, true)).await;
        for kid in [&alice, &bob, &carol] {
            let _ = pg_put_key(&backend, kid, crate::federation::types::identity_type::USER).await;
        }

        let policy = serde_json::json!({ "cohort_scope": "community" });
        pg_put_community(
            &backend,
            crate::federation::tier_ingest::test_support::sign_community(
                &coop,
                crate::federation::Community {
                    prev_head_digest: String::new(),
                    charter_digest: String::new(),
                    community_key_id: coop.clone(),
                    community_name: "Acme Co-op".into(),
                    members: [&alice, &bob, &carol]
                        .iter()
                        .map(|k| crate::federation::CommunityMember {
                            key_id: (*k).clone(),
                            joined_at: now,
                            role: None,
                        })
                        .collect(),
                    founded_at: now,
                    consensus_protocol: "majority".into(),
                    policy_blob: Some(policy.clone()),
                    persist_row_hash: String::new(),
                },
            ),
        )
        .await
        .unwrap();

        let got = backend
            .lookup_community(&pg_id(&coop))
            .await
            .unwrap()
            .expect("community exists");
        assert_eq!(got.community_name, "Acme Co-op");
        assert_eq!(got.members.len(), 3);
        assert_eq!(got.consensus_protocol, "majority");
        assert_eq!(got.policy_blob.as_ref(), Some(&policy));
        assert_eq!(got.persist_row_hash.len(), 64);

        // Membership GIN/@> fan-out returns the community for each member.
        for member in [&alice, &bob, &carol] {
            let communities = backend
                .list_communities_for_member(&pg_id(member))
                .await
                .unwrap();
            assert_eq!(communities.len(), 1, "for member {member}");
            assert_eq!(communities[0].community_key_id, pg_id(&coop));
        }
        let none = backend
            .list_communities_for_member(&format!("nobody-{suffix}"))
            .await
            .unwrap();
        assert!(none.is_empty());
    }

    /// v4.14.0 (CIRISPersist#152, CEG 0.18 §10.1.4) — the self/family
    /// at-rest DEK cascade end-to-end on Postgres (parity with the sqlite
    /// `at_rest_self_cascade_round_trip_and_fail_secure`): ciphertext at
    /// rest, granted recipient reads plaintext, fail-secure exclusion of a
    /// keyless occurrence, NotGranted for a non-recipient.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn at_rest_self_cascade_round_trip_and_fail_secure_pg() {
        use crate::federation::at_rest_cascade::orchestrate::{
            encrypt_and_cascade, read_for_viewer,
        };
        use crate::federation::types::cohort_scope::SELF;
        use crate::federation::{BlobStorage, EncryptionPubkeys, FederationDirectory};
        use base64::{engine::general_purpose::STANDARD as B64, Engine as _};

        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();

        let now = chrono::Utc::now();
        let suffix = uuid_like();
        let root = format!("root-{suffix}");
        let keyed = format!("occ-keyed-{suffix}");
        let bare = format!("occ-bare-{suffix}");
        let outsider = format!("outsider-{suffix}");
        for kid in [&root, &keyed, &bare, &outsider] {
            pg_put_key_rec(&backend, &fix_section_i_key(kid, "acme", now, true)).await;
        }
        // v62.0.0: every key is named by its kid from here on (the local
        // occurrence door and the cascade read the store's ids).
        let (root, keyed, bare, outsider) =
            (pg_id(&root), pg_id(&keyed), pg_id(&bare), pg_id(&outsider));

        let x_pub = ciris_crypto::x25519::public_from_secret(&[0x42; 32]);
        let (_mp, ml_pub) = ciris_crypto::ml_kem::generate_keypair().unwrap();

        let occ =
            |occ_key: &str, enc: Option<EncryptionPubkeys>| crate::federation::IdentityOccurrence {
                identity_key_id: root.clone(),
                occurrence_key_id: occ_key.into(),
                device_class: crate::federation::types::device_class::LAPTOP.into(),
                hardware_attestation: None,
                asserted_at: now,
                valid_until: None,
                encryption_pubkeys: enc,
                transport_binding: None,
                persist_row_hash: String::new(),
            };
        backend
            .test_seam_put_identity_occurrence(occ(
                &keyed,
                Some(EncryptionPubkeys {
                    x25519_base64: B64.encode(x_pub),
                    ml_kem_768_base64: B64.encode(&ml_pub),
                }),
            ))
            .await
            .unwrap();
        backend
            .test_seam_put_identity_occurrence(occ(&bare, None))
            .await
            .unwrap();

        let plaintext = b"a private note, scoped to self (pg)";
        let result = encrypt_and_cascade(
            &backend,
            SELF,
            &root,
            plaintext,
            Some("text/plain"),
            None,
            Some(&keyed),
        )
        .await
        .unwrap();
        assert_eq!(result.granted, vec![keyed.clone()]);
        assert_eq!(result.excluded, vec![bare.clone()]);

        // Ciphertext at rest (≠ plaintext) carrying the at-rest magic.
        let stored = backend
            .get_blob(&result.at_rest_sha256)
            .await
            .unwrap()
            .expect("bytes present");
        let stored_bytes = match stored {
            crate::federation::BlobBody::Inline(b) => b,
            other => panic!("expected inline ciphertext, got {other:?}"),
        };
        assert_ne!(stored_bytes, plaintext.to_vec());
        assert!(crate::federation::at_rest_cascade::AtRestEnvelope::has_magic(&stored_bytes));

        // No holds_bytes (structural invisibility).
        assert!(backend
            .list_local_holders(&result.at_rest_sha256)
            .await
            .unwrap()
            .is_empty());

        // Granted recipient reads plaintext back.
        let recovered = read_for_viewer(&backend, &result.at_rest_sha256, &keyed)
            .await
            .unwrap();
        assert_eq!(recovered, plaintext);

        // Fail-secure-excluded + non-recipient both → NotGranted.
        for viewer in [&bare, &outsider] {
            let err = read_for_viewer(&backend, &result.at_rest_sha256, viewer)
                .await
                .unwrap_err();
            assert!(
                matches!(err, crate::federation::BlobError::NotGranted { .. }),
                "viewer {viewer} must be denied, got: {err:?}"
            );
        }

        // Only the keyed occurrence holds a grant row.
        let recipients = backend
            .list_at_rest_grant_recipients(&result.at_rest_sha256)
            .await
            .unwrap();
        assert_eq!(recipients, vec![keyed.clone()]);
    }

    /// v6.1.0 (CIRISPersist#161 Ask 2/4, CEG §11.7.1 / §10.1.4) — the
    /// membership-change re-key keystone on Postgres (parity with the
    /// sqlite `rekey_*` tests): a newcomer family member gains access to a
    /// pre-existing family blob via the retroactive ADD walk; a keyless
    /// newcomer is fail-secure excluded; both are idempotent; the
    /// membership `hard_case:*` rows are emitted.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn rekey_family_member_add_keystone_pg() {
        use crate::federation::at_rest_cascade::orchestrate::{
            encrypt_and_cascade, read_for_viewer, rekey_family_member_add,
        };
        use crate::federation::hard_case::{kind, HardCaseFilter};
        use crate::federation::types::cohort_scope::FAMILY;
        use crate::federation::{EncryptionPubkeys, FederationDirectory};
        use base64::{engine::general_purpose::STANDARD as B64, Engine as _};

        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        // v57.0.0 (#988 item 2) — a hard_case row needs this node's key.
        crate::federation::hard_case::test_support::declare_node(
            &backend,
            &format!("pg-test-node-{}", uuid::Uuid::new_v4().simple()),
        )
        .await;

        let now = chrono::Utc::now();
        let s = uuid_like();
        // v62.0.0 (wave T1): the seeds (`*_s`) sign the family; the store holds
        // kids, which every read names.
        let fam_s = format!("fam-{s}");
        let alice_s = format!("alice-{s}");
        let carol_s = format!("carol-{s}");
        let bob_s = format!("bob-{s}");
        let alice_p_s = format!("alice-phone-{s}");
        let carol_p_s = format!("carol-phone-{s}");
        let bob_p_s = format!("bob-phone-{s}");
        for kid in [
            &fam_s, &alice_s, &carol_s, &bob_s, &alice_p_s, &carol_p_s, &bob_p_s,
        ] {
            pg_put_key_rec(&backend, &fix_section_i_key(kid, "acme", now, true)).await;
        }
        let (fam, alice, carol, bob) = (
            pg_id(&fam_s),
            pg_id(&alice_s),
            pg_id(&carol_s),
            pg_id(&bob_s),
        );
        let (alice_p, carol_p, bob_p) = (pg_id(&alice_p_s), pg_id(&carol_p_s), pg_id(&bob_p_s));

        let keyed = |occ_key: &str, identity: &str, seed: u8| {
            let x_pub = ciris_crypto::x25519::public_from_secret(&[seed; 32]);
            let (_mp, ml_pub) = ciris_crypto::ml_kem::generate_keypair().unwrap();
            crate::federation::IdentityOccurrence {
                identity_key_id: identity.into(),
                occurrence_key_id: occ_key.into(),
                device_class: crate::federation::types::device_class::LAPTOP.into(),
                hardware_attestation: None,
                asserted_at: now,
                valid_until: None,
                encryption_pubkeys: Some(EncryptionPubkeys {
                    x25519_base64: B64.encode(x_pub),
                    ml_kem_768_base64: B64.encode(&ml_pub),
                }),
                transport_binding: None,
                persist_row_hash: String::new(),
            }
        };
        let bare = |occ_key: &str, identity: &str| crate::federation::IdentityOccurrence {
            identity_key_id: identity.into(),
            occurrence_key_id: occ_key.into(),
            device_class: crate::federation::types::device_class::LAPTOP.into(),
            hardware_attestation: None,
            asserted_at: now,
            valid_until: None,
            encryption_pubkeys: None,
            transport_binding: None,
            persist_row_hash: String::new(),
        };

        // alice founds the family + writes a family blob.
        backend
            .test_seam_put_identity_occurrence(keyed(&alice_p, &alice, 0x11))
            .await
            .unwrap();
        let family = |members: Vec<&str>| {
            crate::federation::tier_ingest::test_support::sign_family(
                &fam_s,
                crate::federation::Family {
                    prev_head_digest: String::new(),
                    charter_digest: String::new(),
                    family_key_id: fam_s.clone(),
                    family_name: "Household".into(),
                    members: members
                        .into_iter()
                        .map(|k| crate::federation::FamilyMember {
                            key_id: k.into(),
                            joined_at: now,
                            role: None,
                        })
                        .collect(),
                    founded_at: now,
                    consensus_protocol: "unanimous".into(),
                    consensus_protocol_entrenched: false,
                    dissolved_at: None,
                    persist_row_hash: String::new(),
                },
            )
        };
        // Roster is set up front (V067 models removal, not roster
        // mutation): alice + bob + carol. Only alice has an occurrence at
        // write time, so the blob reaches only alice-phone; bob's keyed
        // occurrence and carol's keyless one are registered afterwards.
        pg_put_family(&backend, family(vec![&alice_s, &bob_s, &carol_s]))
            .await
            .unwrap();
        let plaintext = b"family blob written before bob/carol registered devices (pg)";
        let result = encrypt_and_cascade(
            &backend,
            FAMILY,
            &fam,
            plaintext,
            None,
            None,
            Some(&alice_p),
        )
        .await
        .unwrap();
        assert_eq!(result.granted, vec![alice_p.clone()]);

        // bob registers a KEYED occurrence → gains access via the walk.
        backend
            .test_seam_put_identity_occurrence(keyed(&bob_p, &bob, 0x22))
            .await
            .unwrap();
        let observed = chrono::Utc::now();
        let rk = rekey_family_member_add(&backend, &fam, &bob, observed)
            .await
            .unwrap();
        assert_eq!(rk.blobs_scanned, 1);
        assert_eq!(rk.granted, vec![(bob_p.clone(), 1)]);
        assert!(rk.excluded.is_empty());
        let recovered = read_for_viewer(&backend, &result.at_rest_sha256, &bob_p)
            .await
            .unwrap();
        assert_eq!(recovered, plaintext);

        // Idempotent: a second walk at the same instant adds zero grants.
        let rk2 = rekey_family_member_add(&backend, &fam, &bob, observed)
            .await
            .unwrap();
        assert_eq!(rk2.granted, vec![(bob_p.clone(), 0)]);

        // carol registers a KEYLESS occurrence → fail-secure excluded.
        backend
            .test_seam_put_identity_occurrence(bare(&carol_p, &carol))
            .await
            .unwrap();
        let observed2 = chrono::Utc::now();
        let rk3 = rekey_family_member_add(&backend, &fam, &carol, observed2)
            .await
            .unwrap();
        assert!(rk3.granted.is_empty());
        assert_eq!(rk3.excluded, vec![carol_p.clone()]);
        assert!(read_for_viewer(&backend, &result.at_rest_sha256, &carol_p)
            .await
            .is_err());

        // hard_case rows present for this family (filter by target via the
        // membership-change kind, then narrow to our family_key_id).
        let mc = backend
            .list_hard_case_events(HardCaseFilter {
                kind: Some(kind::FAMILY_MEMBERSHIP_CHANGE.into()),
                since: None,
                emitter_key_id: None,
            })
            .await
            .unwrap();
        assert!(mc
            .iter()
            .any(|e| e.target_key_id.as_deref() == Some(fam.as_str())
                && e.subject_key_id.as_deref() == Some(carol_p.as_str())));
        let exc = backend
            .list_hard_case_events(HardCaseFilter {
                kind: Some(kind::RECIPIENT_EXCLUDED.into()),
                since: None,
                emitter_key_id: None,
            })
            .await
            .unwrap();
        assert!(exc
            .iter()
            .any(|e| e.subject_key_id.as_deref() == Some(carol_p.as_str())));
    }

    /// v9.0.0 G5 (CC 4.4.3.2.1 / 4.4.3.2.2) — PG parity for the community
    /// DEK cascade + rotation-on-removal: v2 key_grant per keyed member,
    /// fail-secure exclude + hard_case for a keyless member, the
    /// infrastructure plaintext opt-out, rotation-on-removal forward
    /// secrecy, and the v2-only guarantee — all run-scoped by `uuid_like`.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn community_dek_cascade_rotation_and_v2_only_pg() {
        // v62.0.0 (wave T1 + lead's ruling 1): the rooms land by their voices,
        // the occurrences through the local door, and every read names keys by
        // kid; the seeds (`*_s`) sign. The rooted-INFRASTRUCTURE-room leg (a
        // canonical trust-root room opts out of the DEK cascade) is gone with
        // the earlier canonical plane: canonical is the bundle's serve nodes
        // (C1/C2). The self-labelled infrastructure room (NOT exempt) stays.
        use crate::federation::community_dek::orchestrate::{
            emit_excluded_hard_cases, encrypt_and_cascade_community, read_for_community_viewer,
        };
        use crate::federation::hard_case::{kind, HardCaseFilter};
        use crate::federation::types::cohort_scope::COMMUNITY;
        use crate::federation::{BlobStorage, EncryptionPubkeys, FederationDirectory};
        use base64::{engine::general_purpose::STANDARD as B64, Engine as _};

        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();

        let now = chrono::Utc::now();
        let s = uuid_like();
        let comm_s = format!("comm-{s}");
        let fakeinfra_s = format!("fakeinfra-{s}");
        let minter_s = format!("node-{s}");
        let alice_s = format!("alice-{s}");
        let bob_s = format!("bob-{s}");
        let alice_p_s = format!("alice-occ-{s}");
        let bob_p_s = format!("bob-occ-{s}");
        // Community members (alice/bob) are user-role humans; the rest agents,
        // the minter a node. v62.0.0 (round 3, E8) — the members' occurrence
        // keys are their own devices, so user-typed: an occurrence never binds
        // a node or agent key to a person (`occurrence_mixes_person_and_machine`,
        // CC 3.3.6).
        let _ = pg_put_key(
            &backend,
            &minter_s,
            crate::federation::types::identity_type::NODE,
        )
        .await;
        for kid in [&alice_p_s, &bob_p_s] {
            let _ = pg_put_key(&backend, kid, crate::federation::types::identity_type::USER).await;
        }
        for kid in [&comm_s, &fakeinfra_s] {
            let _ = pg_put_key(
                &backend,
                kid,
                crate::federation::types::identity_type::AGENT,
            )
            .await;
        }
        // v62.0.0 (P1-fix4; CC rc21 3.3.6) — alice's and bob's LAPTOP
        // occurrences are person keys (a machine key is never an occurrence
        // of a person).
        for kid in [&alice_s, &bob_s, &alice_p_s, &bob_p_s] {
            let _ = pg_put_key(&backend, kid, crate::federation::types::identity_type::USER).await;
        }
        let (comm, fakeinfra, minter) = (pg_id(&comm_s), pg_id(&fakeinfra_s), pg_id(&minter_s));
        let (alice, bob, alice_p, bob_p) = (
            pg_id(&alice_s),
            pg_id(&bob_s),
            pg_id(&alice_p_s),
            pg_id(&bob_p_s),
        );
        backend.set_node_key_id(&minter);

        let keyed = |occ_key: &str, identity: &str, seed: u8| {
            let x_pub = ciris_crypto::x25519::public_from_secret(&[seed; 32]);
            let (_mp, ml_pub) = ciris_crypto::ml_kem::generate_keypair().unwrap();
            crate::federation::IdentityOccurrence {
                identity_key_id: identity.into(),
                occurrence_key_id: occ_key.into(),
                device_class: crate::federation::types::device_class::LAPTOP.into(),
                hardware_attestation: None,
                asserted_at: now,
                valid_until: None,
                encryption_pubkeys: Some(EncryptionPubkeys {
                    x25519_base64: B64.encode(x_pub),
                    ml_kem_768_base64: B64.encode(&ml_pub),
                }),
                transport_binding: None,
                persist_row_hash: String::new(),
            }
        };
        let bare = |occ_key: &str, identity: &str| crate::federation::IdentityOccurrence {
            identity_key_id: identity.into(),
            occurrence_key_id: occ_key.into(),
            device_class: crate::federation::types::device_class::LAPTOP.into(),
            hardware_attestation: None,
            asserted_at: now,
            valid_until: None,
            encryption_pubkeys: None,
            transport_binding: None,
            persist_row_hash: String::new(),
        };
        backend
            .test_seam_put_identity_occurrence(keyed(&alice_p, &alice, 0x11))
            .await
            .unwrap();
        backend
            .test_seam_put_identity_occurrence(bare(&bob_p, &bob))
            .await
            .unwrap();
        // v62.0.0 (KR-fix31b; CC 5.2 "a write its own author cannot open is
        // refused") — the minter (the author of every `None`-author write
        // below) is alice's owned, keyed device: a two-voice owner binding and
        // its own self pair with this store's content-KEM keys
        // (`two_node::place_device`). It is granted after alice's occurrence.
        let kem_id = backend.load_or_init_content_kem_identity().await.unwrap();
        crate::federation::key_grant_invariants::two_node::place_device(
            &backend,
            &alice_s,
            &minter,
            &minter_s,
            crate::federation::types::device_class::LAPTOP,
            Some(EncryptionPubkeys {
                x25519_base64: kem_id.x25519_pubkey_b64,
                ml_kem_768_base64: kem_id.ml_kem_768_pubkey_b64,
            }),
        )
        .await;

        crate::federation::tier_ingest::test_support::register_fixture_infrastructure_founder(
            &backend,
        )
        .await;
        let community = |key: &str, members: Vec<&str>, policy: Option<serde_json::Value>| {
            crate::federation::tier_ingest::test_support::sign_community(
                key,
                crate::federation::Community {
                    prev_head_digest: String::new(),
                    charter_digest: String::new(),
                    community_key_id: key.into(),
                    community_name: "Co-op".into(),
                    members: crate::federation::tier_ingest::test_support::fixture_members(
                        policy.as_ref(),
                        members
                            .into_iter()
                            .map(|k| crate::federation::CommunityMember {
                                key_id: k.into(),
                                joined_at: now,
                                role: None,
                            })
                            .collect(),
                    ),
                    founded_at: now,
                    consensus_protocol:
                        crate::federation::tier_ingest::test_support::fixture_protocol(
                            policy.as_ref(),
                            "majority",
                        ),
                    policy_blob: policy,
                    persist_row_hash: String::new(),
                },
            )
        };

        // ── non-infra community: keyed alice granted, keyless bob excluded.
        pg_put_community(&backend, community(&comm_s, vec![&alice_s, &bob_s], None))
            .await
            .unwrap();
        let r0 = encrypt_and_cascade_community(
            &backend,
            &comm,
            b"minutes (pg)",
            Some("text/plain"),
            None,
        )
        .await
        .unwrap();
        assert_eq!(r0.epoch, 0);
        assert_eq!(r0.granted, vec![alice_p.clone(), minter.clone()]);
        assert_eq!(r0.excluded, vec![bob_p.clone()]);
        assert_eq!(
            read_for_community_viewer(&backend, &r0.at_rest_sha256, &alice_p)
                .await
                .unwrap(),
            b"minutes (pg)"
        );
        assert!(matches!(
            read_for_community_viewer(&backend, &r0.at_rest_sha256, &bob_p)
                .await
                .unwrap_err(),
            crate::federation::BlobError::NotGranted { .. }
        ));
        emit_excluded_hard_cases(&backend, &r0, chrono::Utc::now())
            .await
            .unwrap();
        let exc = backend
            .list_hard_case_events(HardCaseFilter {
                kind: Some(kind::RECIPIENT_EXCLUDED.into()),
                since: None,
                emitter_key_id: None,
            })
            .await
            .unwrap();
        assert!(exc
            .iter()
            .any(|e| e.subject_key_id.as_deref() == Some(bob_p.as_str())
                && e.detail.get("cohort_scope").and_then(|v| v.as_str()) == Some(COMMUNITY)));

        // ── a community whose own key is NOT the infrastructure authority
        //    (fakeinfra) is NOT exempted: the DEK cascade STILL runs
        //    (fail-secure: a self-applied infra label grants nothing).
        pg_put_community(
            &backend,
            community(
                &fakeinfra_s,
                vec![&alice_s],
                Some(serde_json::json!({ "cohort_subkind": "infrastructure" })),
            ),
        )
        .await
        .unwrap();
        let fake =
            encrypt_and_cascade_community(&backend, &fakeinfra, b"not canonical", None, None)
                .await
                .expect("unauthorized infra label must NOT opt out of the DEK cascade");
        assert_eq!(fake.epoch, 0);
        assert_eq!(fake.granted, vec![alice_p.clone(), minter.clone()]);
        assert!(backend
            .community_dek_get_self_retention(&fakeinfra, &minter, 0)
            .await
            .unwrap()
            .is_some());

        // ── rotation on removal: bob leaves on their own signature (v49.0.0,
        //    #908); the epoch bumps, a new write is epoch 1, the old blob stays
        //    readable to alice.
        pg_put_community_revocation(
            &backend,
            crate::federation::tier_ingest::test_support::sign_community_membership_revocation(
                &bob_s,
                crate::federation::CommunityMembershipRevocation {
                    community_key_id: comm_s.clone(),
                    removed_identity_key_id: bob_s.clone(),
                    removed_at: now,
                    effective_at: now,
                    reason: None,
                    witness_set: vec![],
                    persist_row_hash: String::new(),
                },
            ),
        )
        .await
        .unwrap();
        assert_eq!(
            backend
                .community_dek_current_epoch(&comm, &minter)
                .await
                .unwrap(),
            1
        );
        let r1 = encrypt_and_cascade_community(&backend, &comm, b"post-removal (pg)", None, None)
            .await
            .unwrap();
        assert_eq!(r1.epoch, 1);
        assert_eq!(r1.granted, vec![alice_p.clone(), minter.clone()]);
        assert_ne!(r0.at_rest_sha256, r1.at_rest_sha256);
        assert_eq!(
            read_for_community_viewer(&backend, &r1.at_rest_sha256, &alice_p)
                .await
                .unwrap(),
            b"post-removal (pg)"
        );
        assert_eq!(
            read_for_community_viewer(&backend, &r0.at_rest_sha256, &alice_p)
                .await
                .unwrap(),
            b"minutes (pg)"
        );

        // ── v2-only: every member grant row is the v2 wrap.
        let client = backend.get_client().await.unwrap();
        let rows = client
            .query(
                "SELECT DISTINCT wrap_algorithm \
                 FROM cirislens.federation_community_dek_member_grants \
                 WHERE community_key_id = $1",
                &[&comm],
            )
            .await
            .unwrap();
        assert!(!rows.is_empty());
        for r in &rows {
            let alg: String = r.get("wrap_algorithm");
            assert_eq!(alg, crate::federation::at_rest_cascade::WRAP_ALGORITHM_V2);
        }
    }

    /// SecReview F4 (PG parity): a FUTURE-DATED community membership
    /// revocation `effective_at` is REJECTED before any write; a non-future
    /// one is accepted AND bumps the DEK epoch. Run-scoped uuid-suffixed ids.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn community_revocation_rejects_future_dated_effective_at_pg() {
        use crate::federation::BlobStorage;
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        let now = chrono::Utc::now();
        let s = uuid_like();
        let comm = format!("comm-f4-{s}");
        // #848 — the revocation bump advances THIS node's own counter.
        let minter = format!("node-f4-{s}");
        backend.set_node_key_id(pg_id(&minter));
        let bob = format!("bob-f4-{s}");
        for kid in [&comm, &bob] {
            pg_put_key_rec(&backend, &fix_section_i_key(kid, "acme", now, true)).await;
        }
        pg_put_community(
            &backend,
            crate::federation::tier_ingest::test_support::sign_community(
                &comm,
                crate::federation::types::Community {
                    prev_head_digest: String::new(),
                    charter_digest: String::new(),
                    community_key_id: comm.to_owned(),
                    community_name: "fixture room".into(),
                    members: vec![],
                    founded_at: "2026-01-01T00:00:00Z".parse().unwrap(),
                    consensus_protocol: "quorum:1/1".into(),
                    policy_blob: None,
                    persist_row_hash: String::new(),
                },
            ),
        )
        .await
        .expect("v48.0.0 (#860): the room row the revocation FK references");
        let rev = |effective: chrono::DateTime<chrono::Utc>| {
            crate::federation::tier_ingest::test_support::sign_community_membership_revocation(
                &bob, /* v49.0.0 (#908): the member leaves on their own signature */
                crate::federation::CommunityMembershipRevocation {
                    community_key_id: comm.clone(),
                    removed_identity_key_id: bob.clone(),
                    removed_at: effective,
                    effective_at: effective,
                    reason: None,
                    witness_set: vec![],
                    persist_row_hash: String::new(),
                },
            )
        };
        let future = chrono::Utc::now() + chrono::Duration::days(30);
        let err = pg_put_community_revocation(&backend, rev(future))
            .await
            .unwrap_err();
        assert!(
            matches!(err, crate::federation::Error::InvalidArgument(_)),
            "future-dated effective_at must be rejected, got {err:?}"
        );
        assert_eq!(
            backend
                .community_dek_current_epoch(&pg_id(&comm), &pg_id(&minter))
                .await
                .unwrap(),
            0
        );
        pg_put_community_revocation(&backend, rev(chrono::Utc::now()))
            .await
            .expect("non-future revocation accepted");
        assert_eq!(
            backend
                .community_dek_current_epoch(&pg_id(&comm), &pg_id(&minter))
                .await
                .unwrap(),
            1
        );
    }

    /// CC 4.4.3.2.8 / #308 (PG parity): the `affiliations` cohort runs the full
    /// membership lifecycle (add → active-members → revoke + epoch bump) through
    /// the SAME community machinery on the Postgres backend.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn affiliations_cohort_membership_lifecycle_pg() {
        // v62.0.0 (wave T1 v3): the add is a widening at the edition-2 group
        // door (the member's proposal and acceptance held as edition-2 rows,
        // then the widening's voices, I3004); the removal is a membership
        // removal under the held roster version. Every id is a kid.
        use crate::federation::cohort::Cohort;
        use crate::federation::edition2::ingest::StatementOutcome;
        use crate::federation::membership_acceptance::test_support::{
            acceptance_row, proposal_row,
        };
        use crate::federation::{BlobStorage, FederationDirectory};
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        let now = chrono::Utc::now();
        let suffix = uuid_like();
        let coop = format!("aff-coop-{suffix}");
        // #848 — the revocation bump advances THIS node's own counter.
        let minter = format!("aff-node-{suffix}");
        backend.set_node_key_id(pg_id(&minter));
        let alice = format!("aff-alice-{suffix}");
        let carol = format!("aff-carol-{suffix}");
        // Community key (infra-class) + two user-role human members.
        pg_put_key_rec(&backend, &fix_section_i_key(&coop, "acme", now, true)).await;
        for kid in [&alice, &carol] {
            let _ = pg_put_key(&backend, kid, crate::federation::types::identity_type::USER).await;
        }
        pg_put_community(
            &backend,
            crate::federation::tier_ingest::test_support::sign_community(
                &coop,
                crate::federation::Community {
                    prev_head_digest: String::new(),
                    charter_digest: String::new(),
                    community_key_id: coop.clone(),
                    community_name: "Affiliations Co-op".into(),
                    members: vec![crate::federation::CommunityMember {
                        key_id: alice.clone(),
                        joined_at: now,
                        role: None,
                    }],
                    founded_at: now,
                    consensus_protocol: "majority".into(),
                    policy_blob: Some(serde_json::json!({ "cohort_scope": "affiliations" })),
                    persist_row_hash: String::new(),
                },
            ),
        )
        .await
        .unwrap();

        // add carol via the affiliations cohort: alice (a majority of one)
        // proposes, carol accepts, then alice's widening voice lands.
        // v62.0.0 (round 3, E8) — the proposal names the group by the id the
        // store holds (its kid), as T1's I3004 does: the proposal's
        // `{family,community}_key_id` is no identity-ref member of its
        // payload, so the fixture codec carries it as written, and the growth
        // gate (`check_growth_accepted`) matches the acceptance's group to the
        // widening's by that text.
        let p = proposal_row(
            &alice,
            "affiliations",
            &pg_id(&coop),
            &pg_id(&carol),
            Some("member"),
            now,
        );
        e2::put_signed(&backend, &p).await.expect("the proposal");
        e2::put_signed(&backend, &acceptance_row(&carol, &p, now))
            .await
            .expect("carol's acceptance");
        let (head, _) = e2::held_head(&backend, &pg_id(&coop))
            .await
            .expect("the roster is held");
        let widening =
            crate::federation::tier_ingest::test_support::sign_community_membership_widening(
                &alice,
                crate::federation::types::CommunityMembershipWidening {
                    community_key_id: coop.clone(),
                    member_key_id: carol.clone(),
                    joined_at: now,
                    effective_at: now,
                    role: Some("member".into()),
                    persist_row_hash: String::new(),
                },
            );
        assert!(
            matches!(
                e2::put_voices(
                    &backend,
                    &e2::community_widening_voices(&widening, Some(&head))
                )
                .await
                .expect("affiliations widening"),
                StatementOutcome::Row { .. }
            ),
            "the widening lands"
        );

        let active: Vec<String> = backend
            .active_members(Cohort::Affiliations, &pg_id(&coop))
            .await
            .unwrap()
            .into_iter()
            .map(|m| m.key_id)
            .collect();
        assert!(active.contains(&pg_id(&carol)));
        // v54.0.0 (Codex round 2 on PR #1050) — the roster is shared storage,
        // but the record declares `affiliations`: read under `community` it is
        // refused, never answered with the same roster (I606).
        assert!(
            matches!(
                backend
                    .active_members(Cohort::Community, &pg_id(&coop))
                    .await,
                Err(crate::federation::Error::AffiliationCohortMismatch { .. })
            ),
            "an affiliation read under the community cohort is a cohort mismatch"
        );

        assert_eq!(
            backend
                .community_dek_current_epoch(&pg_id(&coop), &pg_id(&minter))
                .await
                .unwrap(),
            0
        );
        // v49.0.0 (#908): the member leaves on their own signature.
        pg_put_community_revocation(
            &backend,
            crate::federation::tier_ingest::test_support::sign_community_membership_revocation(
                &carol,
                crate::federation::CommunityMembershipRevocation {
                    community_key_id: coop.clone(),
                    removed_identity_key_id: carol.clone(),
                    removed_at: chrono::Utc::now(),
                    effective_at: chrono::Utc::now(),
                    reason: Some("left".into()),
                    witness_set: Vec::new(),
                    persist_row_hash: String::new(),
                },
            ),
        )
        .await
        .expect("affiliations removal");
        assert_eq!(
            backend
                .community_dek_current_epoch(&pg_id(&coop), &pg_id(&minter))
                .await
                .unwrap(),
            1,
            "affiliations removal bumps the CommunityDek epoch (forward secrecy)"
        );
        let active_after: Vec<String> = backend
            .active_members(Cohort::Affiliations, &pg_id(&coop))
            .await
            .unwrap()
            .into_iter()
            .map(|m| m.key_id)
            .collect();
        assert!(!active_after.contains(&pg_id(&carol)));
    }

    /// SecReview F5 (PG parity): INSERT + hard_case + epoch-bump are ONE
    /// transaction — if the epoch bump fails, the revocation INSERT is
    /// rolled back. Induce a deterministic bump failure by pre-seeding the
    /// epoch row at i64::MAX so the in-transaction `epoch + 1` overflows
    /// bigint, then assert NEITHER the revocation row NOR a hard_case event
    /// was committed. Run-scoped uuid-suffixed ids.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn community_revocation_atomic_on_bump_failure_pg() {
        use crate::federation::hard_case::{kind, HardCaseFilter};
        use crate::federation::FederationDirectory;
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        let now = chrono::Utc::now();
        let s = uuid_like();
        let comm = format!("comm-f5-{s}");
        let bob = format!("bob-f5-{s}");
        for kid in [&comm, &bob] {
            pg_put_key_rec(&backend, &fix_section_i_key(kid, "acme", now, true)).await;
        }
        pg_put_community(
            &backend,
            crate::federation::tier_ingest::test_support::sign_community(
                &comm,
                crate::federation::types::Community {
                    prev_head_digest: String::new(),
                    charter_digest: String::new(),
                    community_key_id: comm.to_owned(),
                    community_name: "fixture room".into(),
                    members: vec![],
                    founded_at: "2026-01-01T00:00:00Z".parse().unwrap(),
                    consensus_protocol: "quorum:1/1".into(),
                    policy_blob: None,
                    persist_row_hash: String::new(),
                },
            ),
        )
        .await
        .expect("v48.0.0 (#860): the room row the revocation FK references");
        // Pre-seed the epoch at i64::MAX so the in-transaction `epoch + 1`
        // overflows bigint (deterministic bump failure). #848 — the counter
        // the revocation bumps is THIS node's own, so the node key is set.
        let node_for_bump = format!("node-{s}");
        backend.set_node_key_id(pg_id(&node_for_bump));
        {
            let client = backend.get_client().await.unwrap();
            client
                .execute(
                    "INSERT INTO cirislens.federation_community_dek_epoch \
                        (community_key_id, minter_key_id, epoch, rotated_at) \
                     VALUES ($1, $2, $3, NOW())",
                    &[&pg_id(&comm), &pg_id(&node_for_bump), &i64::MAX],
                )
                .await
                .unwrap();
        }
        let rev =
            crate::federation::tier_ingest::test_support::sign_community_membership_revocation(
                &bob, /* v49.0.0 (#908): the member leaves on their own signature */
                crate::federation::CommunityMembershipRevocation {
                    community_key_id: comm.clone(),
                    removed_identity_key_id: bob.clone(),
                    removed_at: now,
                    effective_at: now,
                    reason: None,
                    witness_set: vec![],
                    persist_row_hash: String::new(),
                },
            );
        let err = pg_put_community_revocation(&backend, rev)
            .await
            .unwrap_err();
        assert!(
            matches!(err, crate::federation::Error::Backend(_)),
            "bump overflow should surface, got {err:?}"
        );
        // The revocation INSERT rolled back — no durable revocation row.
        assert!(backend
            .list_community_membership_revocations_for(&pg_id(&comm))
            .await
            .unwrap()
            .is_empty());
        // And no hard_case event was committed either.
        let events = backend
            .list_hard_case_events(HardCaseFilter {
                kind: Some(kind::COMMUNITY_MEMBERSHIP_CHANGE.into()),
                since: None,
                emitter_key_id: None,
            })
            .await
            .unwrap();
        assert!(
            !events
                .iter()
                .any(|e| e.subject_key_id.as_deref() == Some(pg_id(&bob).as_str())),
            "hard_case must roll back with the txn"
        );
    }

    /// v6.2.0 (#161 A4/A5) — PG parity for the roster-grow forward path:
    /// a genuinely-new member (NOT on the roster at write time) is added by
    /// `rekey_family_member_add` (exercising the `add_family_member` UPDATE
    /// path + concurrent-guard) and is then served a FUTURE family write.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn add_family_member_grows_roster_and_serves_future_writes_pg() {
        // v62.0.0 (wave T1 v3): the family is founded by its voices, bob joins
        // by a widening at the group door (his proposal and acceptance held
        // first, I3004), and every read names keys by kid. The seeds (`*_s`)
        // sign; the kids are what the store holds.
        use crate::federation::at_rest_cascade::orchestrate::{
            encrypt_and_cascade, read_for_viewer, rekey_family_member_add,
        };
        use crate::federation::membership_acceptance::test_support::{
            acceptance_row, proposal_row,
        };
        use crate::federation::types::cohort_scope::FAMILY;
        use crate::federation::{EncryptionPubkeys, FederationDirectory};
        use base64::{engine::general_purpose::STANDARD as B64, Engine as _};

        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();

        let now = chrono::Utc::now();
        let s = uuid_like();
        let fam_s = format!("fam-{s}");
        let alice_s = format!("alice-{s}");
        let bob_s = format!("bob-{s}");
        let alice_p_s = format!("alice-phone-{s}");
        let bob_p_s = format!("bob-phone-{s}");
        for kid in [&fam_s, &alice_s, &bob_s, &alice_p_s, &bob_p_s] {
            pg_put_key_rec(&backend, &fix_section_i_key(kid, "acme", now, true)).await;
        }
        let (fam, alice, bob, alice_p, bob_p) = (
            pg_id(&fam_s),
            pg_id(&alice_s),
            pg_id(&bob_s),
            pg_id(&alice_p_s),
            pg_id(&bob_p_s),
        );
        let keyed = |occ_key: &str, identity: &str, seed: u8| {
            let x_pub = ciris_crypto::x25519::public_from_secret(&[seed; 32]);
            let (_mp, ml_pub) = ciris_crypto::ml_kem::generate_keypair().unwrap();
            crate::federation::IdentityOccurrence {
                identity_key_id: identity.into(),
                occurrence_key_id: occ_key.into(),
                device_class: crate::federation::types::device_class::LAPTOP.into(),
                hardware_attestation: None,
                asserted_at: now,
                valid_until: None,
                encryption_pubkeys: Some(EncryptionPubkeys {
                    x25519_base64: B64.encode(x_pub),
                    ml_kem_768_base64: B64.encode(&ml_pub),
                }),
                transport_binding: None,
                persist_row_hash: String::new(),
            }
        };
        backend
            .test_seam_put_identity_occurrence(keyed(&alice_p, &alice, 0x11))
            .await
            .unwrap();
        // Roster starts with alice ONLY — bob is genuinely new.
        pg_put_family(
            &backend,
            crate::federation::tier_ingest::test_support::sign_family(
                &fam_s,
                crate::federation::Family {
                    prev_head_digest: String::new(),
                    charter_digest: String::new(),
                    family_key_id: fam_s.clone(),
                    family_name: "Household".into(),
                    members: vec![crate::federation::FamilyMember {
                        key_id: alice_s.clone(),
                        joined_at: now,
                        role: None,
                    }],
                    founded_at: now,
                    consensus_protocol: "unanimous".into(),
                    consensus_protocol_entrenched: false,
                    dissolved_at: None,
                    persist_row_hash: String::new(),
                },
            ),
        )
        .await
        .unwrap();

        let blob1 = encrypt_and_cascade(
            &backend,
            FAMILY,
            &fam,
            b"before bob (pg)",
            None,
            None,
            Some(&alice_p),
        )
        .await
        .unwrap();
        assert_eq!(blob1.granted, vec![alice_p.clone()]);

        backend
            .test_seam_put_identity_occurrence(keyed(&bob_p, &bob, 0x22))
            .await
            .unwrap();
        // v31.0.0 (CIRISPersist#654) — PG parity for the ORDER: the key-less
        // driver refuses a newcomer the roster does not name; the SIGNED
        // admission door is what grows the roster.
        let too_early = rekey_family_member_add(&backend, &fam, &bob, chrono::Utc::now())
            .await
            .expect_err("the driver must not grow the roster itself");
        assert!(
            too_early.to_string().contains("not an active member"),
            "the refusal names the precondition: {too_early}"
        );
        let fam_before = backend.lookup_family(&fam).await.unwrap().unwrap();
        assert!(
            !fam_before.members.iter().any(|m| m.key_id == bob),
            "the refused driver call left the roster alone"
        );
        // v49.0.0 (#910): alice — the whole of this `unanimous` family — signs
        // the family widening; bob's consent is held first.
        // v62.0.0 (round 3, E8) — the proposal names the group by the id the
        // store holds (its kid), as T1's I3004 does: the proposal's
        // `{family,community}_key_id` is no identity-ref member of its
        // payload, so the fixture codec carries it as written, and the growth
        // gate (`check_growth_accepted`) matches the acceptance's group to the
        // widening's by that text.
        let p = proposal_row(&alice_s, "family", &fam, &bob, None, now);
        e2::put_signed(&backend, &p).await.expect("bob's proposal");
        e2::put_signed(&backend, &acceptance_row(&bob_s, &p, now))
            .await
            .expect("bob's acceptance");
        let (head, _) = e2::held_head(&backend, &fam)
            .await
            .expect("the family's roster is held");
        let widening =
            crate::federation::tier_ingest::test_support::sign_family_membership_widening(
                &alice_s,
                crate::federation::types::FamilyMembershipWidening {
                    family_key_id: fam_s.clone(),
                    member_key_id: bob_s.clone(),
                    joined_at: now,
                    effective_at: now,
                    role: None,
                    persist_row_hash: String::new(),
                },
            );
        let voices = e2::family_widening_voices(&widening, Some(&head));
        e2::put_voices(&backend, &voices)
            .await
            .expect("signed roster grow");

        let rk = rekey_family_member_add(&backend, &fam, &bob, chrono::Utc::now())
            .await
            .unwrap();
        assert_eq!(rk.granted, vec![(bob_p.clone(), 1)]);
        assert!(read_for_viewer(&backend, &blob1.at_rest_sha256, &bob_p)
            .await
            .is_ok());

        // Roster grew — by the one fold; the record is the founding one
        // (v49.0.0, #910: growth rides the family widening plane).
        assert!(backend
            .active_family_members(&fam)
            .await
            .unwrap()
            .iter()
            .any(|m| m.key_id == bob));
        assert_eq!(
            backend
                .lookup_family(&fam)
                .await
                .unwrap()
                .unwrap()
                .members
                .len(),
            1
        );

        // Forward path: a NEW write reaches BOTH alice + bob.
        let blob2 = encrypt_and_cascade(
            &backend,
            FAMILY,
            &fam,
            b"after bob (pg)",
            None,
            None,
            Some(&alice_p),
        )
        .await
        .unwrap();
        let mut granted = blob2.granted.clone();
        granted.sort();
        let mut want = vec![alice_p.clone(), bob_p.clone()];
        want.sort();
        assert_eq!(granted, want);

        // Idempotent re-add: the same widening again adds no roster entry.
        e2::put_voices(&backend, &voices)
            .await
            .expect("a re-offered widening is held");
        assert_eq!(
            backend
                .active_family_members(&fam)
                .await
                .unwrap()
                .iter()
                .filter(|m| m.key_id == bob)
                .count(),
            1
        );
    }

    /// §I list_federation_keys round-trip + cursor pagination.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn read_section_i_list_federation_keys_cursor() {
        // v62.0.0 (the JSON cut): an edition-2 key's identity-ref IS its kid,
        // so no filter groups four keys; the witness runs on its own database
        // and pages every key there. The earlier `roles` and PQC-pending
        // columns are not carried (edition 2 has neither).
        let Some(dsn) = pg_isolated_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        use crate::read::ReadEngine;

        // 4 distinct keys; valid_from staggered so cursor ordering is
        // deterministic.
        let base = chrono::Utc::now() - chrono::Duration::hours(2);
        let mut key_ids: Vec<String> = Vec::new();
        for i in 0..4 {
            let seed = format!("k-§i-{}-{i}", uuid_like());
            let kid = e2::put_key_with(
                &backend,
                &seed,
                &[crate::federation::types::identity_type::AGENT],
                // v62.0.0 (E8 round 3) — the projection's `valid_from` is the
                // record's `asserted_at` (`projection::key_projection`), so the
                // stagger rides `asserted_at`: with the default instant all four
                // tie and the page order falls to the key id.
                &e2::KeyRecordOptions {
                    asserted_at_ms: Some(e2::ms(base + chrono::Duration::minutes(i64::from(i)))),
                    valid_from_ms: Some(e2::ms(base + chrono::Duration::minutes(i64::from(i)))),
                    ..Default::default()
                },
            )
            .await;
            key_ids.push(kid);
        }
        key_ids.reverse(); // newest-first

        let filter = crate::read::FederationKeyFilter::default();

        // Page 1
        let p1 = backend
            .list_federation_keys(
                filter.clone(),
                None,
                2,
                crate::scope::CallerScope::Unauthenticated,
            )
            .await
            .unwrap();
        assert_eq!(p1.items.len(), 2);
        assert_eq!(p1.items[0].key_id, key_ids[0]);
        assert_eq!(p1.items[1].key_id, key_ids[1]);
        let c1 = p1.next_cursor.expect("page 2 cursor");

        // Page 2 — exact-fill (2 remaining items, limit=2). The
        // pagination contract (matching §A) is "next_cursor is None
        // only when items.len() < limit"; an exact-match page returns
        // Some(cursor) and the consumer fetches one more page that
        // yields zero items. Page 3 below is the empty-tail probe.
        let p2 = backend
            .list_federation_keys(
                filter.clone(),
                Some(c1),
                2,
                crate::scope::CallerScope::Unauthenticated,
            )
            .await
            .unwrap();
        assert_eq!(p2.items.len(), 2);
        assert_eq!(p2.items[0].key_id, key_ids[2]);
        assert_eq!(p2.items[1].key_id, key_ids[3]);
        let c2 = p2.next_cursor.expect("page 3 cursor (exact-fill page)");

        // Page 3 — empty tail, cursor None.
        let p3 = backend
            .list_federation_keys(
                filter.clone(),
                Some(c2),
                2,
                crate::scope::CallerScope::Unauthenticated,
            )
            .await
            .unwrap();
        assert!(p3.items.is_empty(), "no more items past 4-key fixture");
        assert!(p3.next_cursor.is_none(), "empty page → no cursor");

        // X2 pass 2: E's rewrite drops the PQC-pending filter leg (edition 2
        // carries no PQC-pending column); a stale tail of it survived a merge.
    }

    /// §I list_revocations round-trip.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn read_section_i_list_revocations_round_trip() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        use crate::read::ReadEngine;

        // v62.0.0 (E8 round 3) — the revocation is an edition-2
        // `revocation:{entity_type}:{reason}` statement (T2), landed through
        // the one door into `federation_revocations`. The earlier fixture
        // sealed a JSON revocation over a JCS image with the seed's hybrid
        // key, which an edition-2 key plane does not hold; a key that
        // revokes ANOTHER key needs a slash conferral, so the read witness
        // takes the plain case: a held key revoking itself.
        let now = chrono::Utc::now();
        let victim = format!("victim-§i-{}", uuid_like());
        pg_put_key_rec(
            &backend,
            &fix_section_i_key(&victim, &victim, now - chrono::Duration::minutes(1), false),
        )
        .await;
        let revoked_id = e2::kid(&victim);
        let revoking_id = revoked_id.clone();
        let st = e2::revocation_statement(
            &victim,
            &victim,
            "agent",
            "compromise",
            now,
            now,
            None,
            e2::ms(now),
        );
        let out = e2::put_statement(&backend, &st)
            .await
            .expect("the self-revocation lands on the revocation plane");
        assert!(
            matches!(
                out,
                crate::federation::edition2::ingest::StatementOutcome::Row { .. }
            ),
            "the self-revocation is a row: {out:?}"
        );

        let page = backend
            .list_revocations(
                crate::read::RevocationFilter {
                    revoked_key_id: Some(revoked_id.clone()),
                    ..Default::default()
                },
                None,
                100,
                crate::scope::CallerScope::Unauthenticated,
            )
            .await
            .unwrap();
        assert_eq!(page.items.len(), 1);
        assert_eq!(
            page.items[0].revoked_key_id.as_deref(),
            Some(revoked_id.as_str())
        );
        assert_eq!(page.items[0].revoking_key_id, revoking_id);
    }

