    /// v62.0.0 (round 3, E8; T2.api §6) — the granter of a trust edge: a
    /// live edition-2 key (no end), its id `e2::kid(seed)`. The JSON
    /// `grant_trust` door is earlier-form (`refuse_earlier_form("trust_grant")`):
    /// a trust grant IS a `trust:accepts:v1` edge.
    async fn trust_steward(backend: &PostgresBackend) -> String {
        let seed = format!("trust-steward-{}", uuid_like());
        pg_put_key(
            backend,
            &seed,
            crate::federation::types::identity_type::USER,
        )
        .await;
        seed
    }

    /// A trust grant: the granter's `trust:accepts:v1` edge naming `key`
    /// (seeds), through the statement door; its statement (its row id names
    /// it for a `withdraws`).
    async fn pg_put_trust_edge(
        backend: &PostgresBackend,
        granter: &str,
        key: &str,
        classes: &[&str],
    ) -> Vec<u8> {
        // v62.0.0 (E1-fix2; T2-fix6, CC 3.2 T4a) — an edge to a held registry
        // root names the lineage head it attaches on (`TrustRootHeadUnnamed`
        // otherwise); an edge to a key is unchanged. The sqlite twin is
        // `put_trust_edge`.
        let edge = e2::trust_accepts_edge(
            backend,
            granter,
            key,
            classes,
            None,
            crate::federation::types::cohort_scope::FEDERATION,
            e2::ms(chrono::Utc::now()),
        )
        .await;
        e2::put_statement(backend, &edge)
            .await
            .expect("the trust:accepts edge is admitted");
        edge
    }

    /// v62.0.0 (E1-fix2; CC 3.2, `trust_root::check_trust_charter_admission`)
    /// — **`seed`'s self `trust:accepts` edge as a valid ROOT CHARTER**: a
    /// self-loop `delegates_to` with an `infra:*` scope IS the root charter, and
    /// a root charter carries its `pre_rotation_commitment` (the pre-committed
    /// successor key, as W1's `fixture_trust_root::charter_statement` commits
    /// it). The successor seed leads with its distinguishing part (seeds are
    /// cut at 32 bytes). The sqlite (`self_trust_charter_edge`) twin is the same.
    fn pg_self_trust_charter_edge(seed: &str) -> Vec<u8> {
        use ciris_verify_core::cde::Value;
        let Value::Map(mut m) = crate::federation::edition2::typed::trust_accepts_payload(
            &e2::kid_or_keep(seed),
            &[],
            None,
            crate::federation::types::cohort_scope::FEDERATION,
            e2::ms(chrono::Utc::now()),
        ) else {
            unreachable!("trust_accepts_payload is a map")
        };
        // v62.0.0 (R2-accept) — `trust_accepts_payload` states no `scope`
        // (an acceptance carries none); a self-loop CHARTER row is read by its
        // `infra:*` scope, so this fixture states it.
        m.push((
            Value::Text("scope".to_owned()),
            Value::Array(vec![Value::Text(
                crate::federation::trust_root::INFRA_SERVE_SCOPE.to_owned(),
            )]),
        ));
        let successor = e2::signing_key(&format!("succ-{seed}"));
        let commitment = ciris_verify_core::edition2::recovery::recovery_commitment(&[successor
            .public_key()
            .clone()]);
        m.push((
            Value::Text(crate::federation::trust_root::CHARTER_PRE_ROTATION_FIELD.to_owned()),
            Value::Bytes(commitment.to_vec()),
        ));
        m.sort_by_key(|(k, _)| ciris_verify_core::cde::encode(k));
        e2::typed_statement_as(
            seed,
            "delegates_to",
            seed,
            crate::federation::edition2::typed::TRUST_PREFIX,
            &Value::Map(m),
        )
    }

    /// The granter's `withdraws` of `edge` (the projected row expires).
    async fn pg_withdraw_trust_edge(
        backend: &PostgresBackend,
        granter: &str,
        key: &str,
        edge: &[u8],
    ) -> Vec<u8> {
        let withdraws = e2::trust_withdraws_statement(
            granter,
            key,
            &e2::row_id_of(edge),
            e2::ms(chrono::Utc::now()),
        );
        e2::put_statement(backend, &withdraws)
            .await
            .expect("the granter's withdraws is admitted");
        withdraws
    }

    /// A held community `key` (a registry's root): its key, then a founding
    /// roster through the T1 voices (no members, `quorum:1/1`).
    async fn pg_put_registry_root(backend: &PostgresBackend, key: &str) {
        let now = chrono::Utc::now();
        pg_put_key(
            backend,
            key,
            crate::federation::types::identity_type::PRIMITIVE,
        )
        .await;
        pg_put_community(
            backend,
            crate::federation::tier_ingest::test_support::sign_community(
                key,
                crate::federation::Community {
                    prev_head_digest: String::new(),
                    charter_digest: String::new(),
                    community_key_id: key.to_owned(),
                    community_name: "registry".into(),
                    members: Vec::new(),
                    founded_at: now,
                    consensus_protocol: "quorum:1/1".into(),
                    policy_blob: None,
                    persist_row_hash: String::new(),
                },
            ),
        )
        .await
        .expect("the registry's community is held");
    }

    /// Trust shape 1+2+3: round-trip + self-trust + Registry-without-domains
    /// (run as one composed test because pg runs are serialized and each does
    /// its own connect+migrate). v62.0.0 (T2.api §6) — the grant is a
    /// `trust:accepts:v1` edge; `trust_type` is DERIVED (no reciprocal edge:
    /// `temporary`); a self edge and a Registry edge with no classes are
    /// admitted as edges but project NO trust row (no refusal is raised).
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn trust_pg_grant_lookup_and_validation() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        use crate::federation::FederationDirectory;

        let steward = trust_steward(&backend).await;
        let key_seed = format!("trust-k-{}", uuid_like());
        pg_put_key_rec(
            &backend,
            &fix_section_i_key(&key_seed, "primitive", chrono::Utc::now(), false),
        )
        .await;
        let key_id = e2::kid(&key_seed);

        // Shape 1: round-trip.
        pg_put_trust_edge(&backend, &steward, &key_seed, &[]).await;
        let row = backend.lookup_trust(&key_id).await.unwrap().unwrap();
        assert_eq!(row.key, key_id);
        assert_eq!(row.trust_type, crate::federation::TrustType::Temporary);
        assert_eq!(
            row.trust_relationship,
            crate::federation::TrustRelationship::Direct
        );
        assert_eq!(row.trusted_by, e2::kid(&steward));

        // Shape 2: a self edge projects no trust row.
        let self_seed = format!("trust-self-{}", uuid_like());
        pg_put_key(
            &backend,
            &self_seed,
            crate::federation::types::identity_type::USER,
        )
        .await;
        // v62.0.0 (E1-fix2; CC 3.2) — a self `trust:accepts` edge IS the root
        // charter, so it carries the charter's pre-rotation commitment
        // (`pg_self_trust_charter_edge`); it is admitted as an edge but projects no trust row.
        e2::put_statement(&backend, &pg_self_trust_charter_edge(&self_seed))
            .await
            .expect("the self trust:accepts edge (a root charter) is admitted");
        assert!(
            backend
                .lookup_trust(&e2::kid(&self_seed))
                .await
                .unwrap()
                .is_none(),
            "a self edge projects no trust row"
        );

        // Shape 3: a Registry edge (to a held community) with no classes
        // projects no trust row.
        let reg = format!("trust-reg-{}", uuid_like());
        pg_put_registry_root(&backend, &reg).await;
        pg_put_trust_edge(&backend, &steward, &reg, &[]).await;
        assert!(
            backend
                .lookup_trust(&e2::kid(&reg))
                .await
                .unwrap()
                .is_none(),
            "a Registry edge with no classes projects no trust row"
        );
    }

    /// Trust shape 4+6: revoke idempotent + include_expired filter. v62.0.0
    /// — the revoke is the granter's `withdraws` of the edge (it expires the
    /// projected row); re-offered it changes nothing.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn trust_pg_revoke_idempotent_and_filter_expired() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        use crate::federation::FederationDirectory;

        let steward = trust_steward(&backend).await;
        let key_seed = format!("trust-revoke-{}", uuid_like());
        pg_put_key_rec(
            &backend,
            &fix_section_i_key(&key_seed, "primitive", chrono::Utc::now(), false),
        )
        .await;
        let key_id = e2::kid(&key_seed);
        let edge = pg_put_trust_edge(&backend, &steward, &key_seed, &[]).await;
        let withdraws = pg_withdraw_trust_edge(&backend, &steward, &key_seed, &edge).await;
        let first = backend.lookup_trust(&key_id).await.unwrap().unwrap();
        assert!(first.expires_at.is_some(), "the withdraws expires the row");
        // Second revoke MUST succeed (idempotent) and change nothing.
        e2::put_statement(&backend, &withdraws)
            .await
            .expect("a re-offered withdraws succeeds without error");
        let row = backend.lookup_trust(&key_id).await.unwrap().unwrap();
        assert_eq!(
            row.expires_at, first.expires_at,
            "the second revoke changed nothing"
        );

        // include_expired=false → row excluded; include_expired=true → included.
        let active = backend
            .list_trusted_keys(crate::federation::TrustFilter::default())
            .await
            .unwrap();
        assert!(active.iter().all(|r| r.key != key_id));
        let all = backend
            .list_trusted_keys(crate::federation::TrustFilter {
                include_expired: true,
                ..Default::default()
            })
            .await
            .unwrap();
        assert!(all.iter().any(|r| r.key == key_id));
    }

    /// Trust shape 5: relationship + domain filter scoped to Registry.
    /// v62.0.0 — Direct = an edge to a key; Registry = an edge with classes
    /// to a held community (`trust_classes` are the domains).
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn trust_pg_list_filter_relationship_and_domain() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        use crate::federation::FederationDirectory;

        let steward = trust_steward(&backend).await;
        let domain = format!("alpha-{}", uuid_like());
        let d_seed = format!("trust-d-{}", uuid_like());
        let r_seed = format!("trust-r-{}", uuid_like());
        pg_put_key_rec(
            &backend,
            &fix_section_i_key(&d_seed, "primitive", chrono::Utc::now(), false),
        )
        .await;
        pg_put_registry_root(&backend, &r_seed).await;
        pg_put_trust_edge(&backend, &steward, &d_seed, &[]).await;
        pg_put_trust_edge(&backend, &steward, &r_seed, &[domain.as_str()]).await;
        let (k_direct, k_registry) = (e2::kid(&d_seed), e2::kid(&r_seed));

        let registry_only = backend
            .list_trusted_keys(crate::federation::TrustFilter {
                trust_relationship: Some(crate::federation::TrustRelationship::Registry),
                ..Default::default()
            })
            .await
            .unwrap();
        assert!(registry_only.iter().any(|r| r.key == k_registry));
        assert!(registry_only.iter().all(|r| r.key != k_direct));

        let in_domain = backend
            .list_trusted_keys(crate::federation::TrustFilter {
                trust_relationship: Some(crate::federation::TrustRelationship::Registry),
                domain: Some(domain.clone()),
                ..Default::default()
            })
            .await
            .unwrap();
        assert!(in_domain.iter().any(|r| r.key == k_registry));
    }

    // ─── BlobStorage tests (v2.3, CIRISPersist#103) ────────────────
    //
    // PG parity for the SQLite tests in store/sqlite.rs. Each test is
    // serialized via `serial_test::serial(postgres)` because the
    // shared test DB doesn't isolate writes per-test; rows from one
    // test would otherwise leak into another's `list_holders`. The
    // SHA prefix is randomized via `uuid_like()` so leaked attestation
    // rows still can't accidentally match.

    fn pg_sha256_of(bytes: &[u8]) -> [u8; 32] {
        use sha2::{Digest, Sha256};
        let d = Sha256::digest(bytes);
        let mut out = [0u8; 32];
        out.copy_from_slice(&d);
        out
    }

    /// Mix a per-test random suffix into the byte payload so the
    /// derived SHA differs from any other test's blob. Avoids
    /// cross-test interference on the shared PG test DB.
    fn pg_blob_payload(prefix: &str) -> Vec<u8> {
        format!("{prefix}-{}", uuid_like()).into_bytes()
    }

    async fn pg_blob_bootstrap_host(backend: &PostgresBackend, host_key_id: &str) {
        pg_put_key_rec(
            backend,
            // v62.0.0 (E2-fix2): live 30 days back, so a backdated holding
            // claim (the TTL arms sign past CUSTODY_LIVE_SECS) falls inside
            // the key's own window; an agent key, so now-relative.
            &fix_section_i_key(
                host_key_id,
                host_key_id,
                chrono::Utc::now() - chrono::Duration::days(30),
                false,
            ),
        )
        .await;
        // v9.3.0 (#247) — put_blob_signing's holds_bytes scrub_key_id +
        // the eviction `withdraws` are written under the host's DERIVED
        // federation key_id; register that row too (keyed by the derived
        // id, carrying the host's real pubkeys so the FK resolves and the
        // withdraws hybrid-verifies on a real node).
        //
        // v62.0.0 NOT flipped (E2.md): the derived id is the earlier-form
        // `derive_key_id(alias, ed pubkey)`; once slice B makes a signer's id
        // `kid(alias)` this second registration is the first one and goes.
        //
        // v62.0.0 (E1-fix2): under edition 2 the signer's id IS `kid(alias)`,
        // the record `fix_section_i_key` just put (the sqlite twin is
        // `fed_key_derived`), so only a HELD test registers the second row.
        if e2::emit_edition2() {
            return;
        }
        let derived = pg_derived_id_for(host_key_id);
        let (ed_pk, mldsa_pk) =
            crate::federation::tier_ingest::test_support::hybrid_pubkeys(host_key_id);
        let now = chrono::Utc::now();
        let record = crate::federation::KeyRecord {
            key_id: derived.clone(),
            pubkey_ed25519_base64: ed_pk,
            pubkey_ml_dsa_65_base64: mldsa_pk,
            algorithm: crate::federation::types::algorithm::HYBRID.into(),
            identity_type: crate::federation::types::identity_type::AGENT.into(),
            identity_ref: derived.clone(),
            valid_from: now,
            valid_until: None,
            registration_envelope: serde_json::json!({ "id": derived }),
            original_content_hash: "deadbeef".into(),
            scrub_signature_classical: "c2lnbmF0dXJl".into(),
            scrub_signature_pqc: None,
            scrub_key_id: derived.clone(),
            scrub_timestamp: now,
            pqc_completed_at: None,
            persist_row_hash: String::new(),
            capability_roles: Vec::new(),
            attestation_evidence: Some(
                crate::federation::hardware_attestation::test_support::fresh_accord_holder_evidence(
                ),
            ),
            consent_role: None,
            additional_scrubs: Vec::new(),
        };
        crate::federation::FederationDirectory::put_public_key(
            backend,
            crate::federation::SignedKeyRecord { record },
        )
        .await
        .unwrap();
    }

    /// v9.3.0 (#247) — the DERIVED federation key_id for `alias`'s
    /// deterministic test keypair (`derive_key_id(alias, <ed pubkey>)`).
    /// v62.0.0 (E1-fix2): under edition 2 a signer's id is its identity-ref
    /// `kid(alias)` (cut B, `LocalSigner::federation_id`).
    fn pg_derived_id_for(alias: &str) -> String {
        if e2::emit_edition2() {
            return e2::kid(alias);
        }
        let (ed_pk_b64, _) = crate::federation::tier_ingest::test_support::hybrid_pubkeys(alias);
        let ed_pk = {
            use base64::engine::general_purpose::STANDARD as B64;
            use base64::Engine as _;
            B64.decode(ed_pk_b64).expect("ed pubkey b64")
        };
        ciris_verify_core::fedcode::derive_key_id(alias, &ed_pk)
    }

    // v31.0.0 (CIRISPersist#656) — takes the SHA now, because the declared
    // `original_content_hash` must cover the envelope `put_blob` rebuilds, and
    // that envelope is keyed on the SHA. It used to be `"deadbeef"` — four
    // bytes, in a column that holds a 32-byte digest, which is how a whole
    // release of blob tests could pass without the cross-check existing.
    /// v62.0.0 (E2-fix2) — **a holder's claim on a blob, in the form the
    /// test runs under** (the sqlite twin is `BlobClaim`): the holder's
    /// edition-2 custody `here` statement, offered to `put_blob`.
    /// v62.0.0 (T2-fix11): the earlier `PutBlobAttestation` form is deleted
    /// (ruling 4).
    struct PgBlobClaim {
        holder: String,
        sha256: [u8; 32],
        size: u64,
        at: chrono::DateTime<chrono::Utc>,
    }

    impl PgBlobClaim {
        /// The custody `here` statement this claim is.
        fn statement(&self) -> Vec<u8> {
            e2::custody_statement(
                &self.holder,
                &self.sha256,
                Some(self.size),
                crate::federation::types::cohort_scope::FEDERATION,
                None,
                e2::ms(self.at),
            )
        }

        /// The id the claim's row is stored under: its row id.
        fn id(&self) -> String {
            e2::rid(&e2::row_of_statement(
                &self.statement(),
                crate::federation::types::attestation_tier::FEDERATION,
            ))
        }
    }

    /// `put_blob` in the form the test runs under ([`PgBlobClaim`]).
    async fn pg_put_blob_any(
        backend: &PostgresBackend,
        sha256: &[u8; 32],
        body: crate::federation::BlobBody,
        media_type: Option<&str>,
        claim: PgBlobClaim,
    ) -> Result<(), crate::federation::BlobError> {
        use crate::federation::BlobStorage;
        backend
            .put_blob(sha256, body, media_type, &claim.statement())
            .await
    }

    fn pg_blob_attestation(
        sha256: &[u8; 32],
        attesting_key_id: &str,
        scrub_key_id: &str,
        size: u64,
    ) -> PgBlobClaim {
        pg_blob_attestation_at(
            sha256,
            attesting_key_id,
            scrub_key_id,
            chrono::Utc::now(),
            size,
        )
    }

    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn blob_pg_inline_round_trip() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        use crate::federation::{BlobBody, BlobStorage};
        let host = format!("blob-host-inline-{}", uuid_like());
        pg_blob_bootstrap_host(&backend, &host).await;
        let bytes = pg_blob_payload("inline");
        let sha = pg_sha256_of(&bytes);
        pg_put_blob_any(
            &backend,
            &sha,
            BlobBody::Inline(bytes.clone()),
            Some("application/octet-stream"),
            pg_blob_attestation(&sha, &host, &host, bytes.len() as u64),
        )
        .await
        .expect("put inline");
        let got = backend.get_blob(&sha).await.expect("get").expect("present");
        assert_eq!(got, BlobBody::Inline(bytes));
    }

    /// v3.9.2 (CIRISPersist#153 Ask 5) — store_blob_local persists the
    /// bytes but emits NO holds_bytes attestation (structural
    /// invisibility for cohort_scope self/family). Parity with the
    /// sqlite `store_blob_local_persists_bytes_without_announcing` test.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn blob_pg_store_blob_local_persists_without_announcing() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        use crate::federation::{BlobBody, BlobStorage};
        let bytes = pg_blob_payload("local-only");
        let sha = pg_sha256_of(&bytes);
        backend
            .store_blob_local(
                &sha,
                BlobBody::Inline(bytes.clone()),
                None,
                crate::federation::types::cohort_scope::FEDERATION,
                crate::federation::StorageFloor::resolved(
                    crate::federation::types::cohort_scope::CryptoTier::Plaintext,
                ),
                None,
                None,
            )
            .await
            .expect("store_blob_local");
        // Bytes readable locally.
        let got = backend.get_blob(&sha).await.expect("get").expect("present");
        assert_eq!(got, BlobBody::Inline(bytes));
        // Nothing announced — store_blob_local signs no holding claim.
        assert!(
            backend.list_holders(&sha).await.unwrap().is_empty(),
            "store_blob_local must emit no holding claim"
        );
    }

    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn blob_pg_external_round_trip() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        use crate::federation::{BlobBody, BlobStorage, ExternalRef};
        let host = format!("blob-host-ext-{}", uuid_like());
        pg_blob_bootstrap_host(&backend, &host).await;
        // Random SHA for the external case (we trust the caller's
        // SHA; no bytes to verify against).
        let nanos = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        let mut sha = [0u8; 32];
        sha[..16].copy_from_slice(&nanos.to_be_bytes());
        sha[16..].copy_from_slice(&nanos.to_be_bytes());
        let ext = ExternalRef {
            uri: format!("s3://bucket/{}", uuid_like()),
            size_bytes: 99_999_999,
            media_type: Some("video/mp4".into()),
        };
        pg_put_blob_any(
            &backend,
            &sha,
            BlobBody::External(ext.clone()),
            Some("video/mp4"),
            pg_blob_attestation(&sha, &host, &host, ext.size_bytes),
        )
        .await
        .unwrap();
        let got = backend.get_blob(&sha).await.unwrap().unwrap();
        assert_eq!(got, BlobBody::External(ext));
    }

