    /// and the canonical form is still asserted to admit, on the same backend.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn pg_put_attestation_refuses_removed_attestation_ladder_shape() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        use crate::federation::attestation_query::test_support::AllAttestations as _;
        use crate::federation::FederationDirectory;
        let steward = format!("pg-dep-stw-§116-{}", uuid_like());
        let agent_k = format!("pg-dep-agt-§116-{}", uuid_like());
        pg_put_key_rec(
            &backend,
            &pg_admission_key(
                &steward,
                "registry",
                crate::federation::types::identity_type::STEWARD,
            ),
        )
        .await;
        pg_put_key_rec(
            &backend,
            &pg_admission_key(
                &agent_k,
                "primitive-dep",
                crate::federation::types::identity_type::AGENT,
            ),
        )
        .await;
        // The REMOVED CEG 0.1 shape — refused by name, on two rungs so the
        // witness is not pinned to `l1`, and nothing is stored. v62.0.0: the
        // refusal is the door's (the rung shape is no registered instance of
        // `attestation:*`); persist's own token stays accepted.
        for dim in [
            "attestation:l1:self_verify",
            "attestation:l5:agent_integrity",
        ] {
            let err =
                pg_door_refusal(&backend, &steward, &agent_k, dim, "attestation:self_verify").await;
            pg_assert_dimension_refused(
                &err,
                &pg_dimension_tokens("deprecated_attestation_ladder"),
                dim,
            );
        }
        assert!(
            backend
                .all_attestations_for(&e2::kid(&agent_k))
                .await
                .unwrap()
                .is_empty(),
            "a refused row must not be stored"
        );

        // Canonical 0.2 shape — still admitted. Without this leg a refuse-branch
        // that matched `attestation:` broadly would look correct.
        // v62.0.0 (FS-sig-a; CC 3.1.2.1) — `attestation:self_verify` is a
        // key's row about itself: the canonical leg signs about its signer.
        let att = pg_scores_attestation(&steward, &steward, &steward, "attestation:self_verify");
        let canonical_id = att.attestation_id.clone();
        backend
            .put_attestation(crate::federation::SignedAttestation { attestation: att })
            .await
            .expect("the canonical mechanism form must still be admitted");
        assert!(
            backend
                .get_attestation(&canonical_id)
                .await
                .unwrap()
                .is_some(),
            "the canonical row must be stored"
        );

        // The neighbouring gate keeps its own population: a genuinely
        // versionless dimension is still `missing_version_segment`.
        let err = pg_door_refusal(
            &backend,
            &steward,
            &agent_k,
            "attestation:some_other_mechanism",
            "attestation:self_verify",
        )
        .await;
        pg_assert_dimension_refused(
            &err,
            &pg_dimension_tokens("missing_version_segment"),
            "an unregistered mechanism",
        );
    }

    // ─── v3.0.0 (CIRISPersist#116, CEG 0.2 §10.1.2) — holds_bytes ──
    //     24-hour TTL + ContentMiss feedback (postgres backend).

    fn pg_blob_attestation_at(
        sha256: &[u8; 32],
        attesting_key_id: &str,
        _scrub_key_id: &str,
        scrub_timestamp: chrono::DateTime<chrono::Utc>,
        size: u64,
    ) -> PgBlobClaim {
        // This fixture's whole subject is the holder's INSTANT (it drives the
        // TTL arms): the statement's signed `asserted_at`. v62.0.0 (T2-fix11)
        // — the deleted earlier form's scrub key names nothing now.
        PgBlobClaim {
            holder: attesting_key_id.to_owned(),
            sha256: *sha256,
            size,
            at: scrub_timestamp,
        }
    }

    // ── v3.5.2 (CIRISPersist#130) — list_local_holders PG parity ─

    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn pg_blob_list_local_holders_includes_stale_local_holding() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        use crate::federation::{BlobBody, BlobStorage};
        let host = format!("pg-blob-localtruth-{}", uuid_like());
        pg_blob_bootstrap_host(&backend, &host).await;
        let bytes = pg_blob_payload("local-truth-stale");
        let sha = pg_sha256_of(&bytes);
        let backdated = chrono::Utc::now()
            - chrono::Duration::seconds(crate::federation::custody_ack::CUSTODY_LIVE_SECS)
            - chrono::Duration::hours(1);
        pg_put_blob_any(
            &backend,
            &sha,
            BlobBody::Inline(bytes.clone()),
            None,
            pg_blob_attestation_at(&sha, &host, &host, backdated, bytes.len() as u64),
        )
        .await
        .unwrap();
        // v3.6.4 (#130 reopen): BOTH methods report the holder when
        // the blob is locally held — TTL bypass on local-truth applies
        // to list_holders as well as list_local_holders.
        let federation_holders = backend.list_holders(&sha).await.unwrap();
        assert_eq!(federation_holders, vec![pg_id(&host)]);
        let local_holders = backend.list_local_holders(&sha).await.unwrap();
        assert_eq!(local_holders, vec![pg_id(&host)]);
    }

